   1→//! Scribe - Document actor for reactive CRDT synchronization
   2→//!
   3→//! **Context**: Each open page gets its own Scribe that owns LoroDoc layers
   4→//! and handles bidirectional sync with permission-aware merge logic.
   5→//!
   6→//! **Key responsibilities:**
   7→//! - Own LoroDoc layers for a page
   8→//! - Handle permission checks (viewer/submitter/collaborator)
   9→//! - Apply sync policies (local_only, no_incoming_updates, send_full_snapshot)
  10→//! - Broadcast updates to subscribed PeerActors
  11→//! - Notify UI subscribers of changes
  12→
  13→use std::collections::HashMap;
  14→use std::sync::{Arc, Mutex};
  15→use std::sync::atomic::AtomicU64;
  16→
  17→use ractor::{Actor, ActorProcessingErr, ActorRef};
  18→use tokio::time::{interval, Duration};
  19→use tracing::{debug, error, info, instrument, trace, warn};
  20→
  21→use domains::Layer;
  22→
  23→use crate::layer_unit::LayerUnit;
  24→use crate::message;
  25→use crate::state::{ScribeArgs, ScribeState, SyncMode, normalize_layer_name};
  26→use crate::permit::glob_match;
  27→use crate::ephemeral::{
  28→    route_remote_ephemeral, emit_raw_ephemeral, emit_structured_ephemeral,
  29→    broadcast_ephemeral_to_subscribers,
  30→};
  31→use crate::{
  32→    ScribeMessage, ScribeError, Result,
  33→    sync, query, operations, loro_observer,
  34→};
  35→
  36→// Scribe Actor
  37→
  38→/// Scribe - Document sync actor
  39→///
  40→/// One Scribe per open page. Owns layers, handles sync, broadcasts to peers.
  41→pub struct Scribe;
  42→
  43→impl Scribe {
  44→    pub fn new() -> Self {
  45→        Self
  46→    }
  47→}
  48→
  49→impl Default for Scribe {
  50→    fn default() -> Self {
  51→        Self::new()
  52→    }
  53→}
  54→
  55→impl Actor for Scribe {
  56→    type Msg = ScribeMessage;
  57→    type State = ScribeState;
  58→    type Arguments = ScribeArgs;
  59→
  60→    #[instrument(skip_all, fields(page_id = %args.page_id))]
  61→    async fn pre_start(
  62→        &self,
  63→        myself: ActorRef<Self::Msg>,
  64→        args: Self::Arguments,
  65→    ) -> std::result::Result<Self::State, ActorProcessingErr> {
  66→        let mode_info = args
  67→            .sync_config
  68→            .as_ref()
  69→            .map(|c| format!("mode={:?}, target={:?}", c.mode, c.sync_target))
  70→            .unwrap_or_else(|| "no sync config".to_string());
  71→        info!(page_id = %args.page_id, %mode_info, "Scribe started");
  72→
  73→        // Note: Validation is now handled by kunki/ValidationService via ValidationHandle
  74→        // Derivation is handled by kunki/LuaRuntime
  75→        info!(
  76→            page_id = %args.page_id,
  77→            is_node = args.is_node,
  78→            has_validation_handle = args.validation_handle.is_some(),
  79→            "Scribe initialized (validation delegated to kunki)"
  80→        );
  81→
  82→        // Parse our permit using gurkha::Permit directly
  83→        let (our_permit, static_layers) = if let Some(ref permit_token) = args.our_permit {
  84→            match gurkha::Permit::from_token(permit_token) {
  85→                Ok(permit) => {
  86→                    let static_layers = permit.static_layers(&args.page_id, &args.our_did);
  87→                    info!(
  88→                        page_id = %args.page_id,
  89→                        role = %permit.relationship().unwrap_or("peer"),
  90→                        static_layer_count = static_layers.len(),
  91→                        "Parsed our permit via gurkha::Permit"
  92→                    );
  93→                    (Some(permit), static_layers)
  94→                }
  95→                Err(e) => {
  96→                    warn!(page_id = %args.page_id, error = ?e, "Failed to parse our permit");
  97→                    (None, Vec::new())
  98→                }
  99→            }
 100→        } else {
 101→            debug!(page_id = %args.page_id, "No our_permit, defaulting to full access");
 102→            (None, Vec::new())
 103→        };
 104→
 105→        // Spawn periodic flush timer - saves dirty layers every 10 seconds
 106→        // This prevents blocking the actor on every single operation
 107→        let myself_clone = myself.clone();
 108→        tokio::spawn(async move {
 109→            let mut flush_interval = interval(Duration::from_secs(10));
 110→            loop {
 111→                flush_interval.tick().await;
 112→                let _ = myself_clone.cast(ScribeMessage::Flush);
 113→            }
 114→        });
 115→
 116→        // Spawn periodic reconciliation timer - catches missed syncs every 30 seconds
 117→        // Only for Node mode (Broadcast) - User mode (ToSource) relies on Node to initiate sync
 118→        // This prevents bilateral reconciliation attempts that can cause sync storms
 119→        let is_user_mode = args.sync_config.as_ref().map(|c| c.mode) == Some(SyncMode::ToSource);
 120→        if !is_user_mode {
 121→            let myself_reconcile = myself.clone();
 122→            tokio::spawn(async move {
 123→                let mut reconcile_interval = interval(Duration::from_secs(30));
 124→                loop {
 125→                    reconcile_interval.tick().await;
 126→                    let _ = myself_reconcile.cast(ScribeMessage::ReconcileWithPeers);
 127→                }
 128→            });
 129→        }
 130→
 131→        // Convert args.layers → LayerUnit instances
 132→        let mut units: HashMap<String, LayerUnit> = args.layers
 133→            .into_iter()
 134→            .map(|(name, layer)| (name, LayerUnit::new(layer)))
 135→            .collect();
 136→
 137→        let mut state = ScribeState {
 138→            page_id: args.page_id,
 139→            units: HashMap::new(), // Populated below
 140→            subscribers: Arc::new(std::sync::RwLock::new(HashMap::new())),
 141→            query_subscribers: HashMap::new(),
 142→            // Storage traits
 143→            layer_storage: args.layer_storage,
 144→            vector_storage: args.vector_storage,
 145→            peer_resolver: args.peer_resolver,
 146→            permit_issuer: args.permit_issuer,
 147→            // Sync configuration
 148→            sync_config: args.sync_config,
 149→            sync_event_tx: args.sync_event_tx,
 150→            capture_tx: args.capture_tx,
 151→            capture_seq: AtomicU64::new(0),
 152→            page_update_subscribers: Arc::new(std::sync::RwLock::new(Vec::new())),
 153→            pending_update_source: Arc::new(Mutex::new(None)),
 154→            validation_handle: args.validation_handle,
 155→            our_permit,
 156→            our_did: args.our_did.clone(),
 157→            node_script_shutdown: None,
 158→            pending_layer_authorizations: HashMap::new(),
 159→        };
 160→
 161→        // Pre-create static layers from permit (already extracted via PermitContext)
 162→        // Static layers are fully known after expanding {page_id} and {aud}
 163→        // Dynamic layers (with wildcards) are created on-demand during sync
 164→        for layer_name in static_layers {
 165→            if !units.contains_key(&layer_name) {
 166→                info!(
 167→                    page_id = %state.page_id,
 168→                    layer = %layer_name,
 169→                    "Pre-creating static layer from permit"
 170→                );
 171→                units.insert(layer_name, LayerUnit::new_empty());
 172→            }
 173→        }
 174→
 175→        // Set is_local_only on each unit based on permit
 176→        for (name, unit) in units.iter_mut() {
 177→            unit.set_local_only(!state.should_sync_layer(name));
 178→        }
 179→
 180→        // Move units into state
 181→        state.units = units;
 182→
 183→        // Set up Loro observers for all layers (including pre-created ones)
 184→        // This ensures import() triggers broadcasts via observer pattern
 185→        loro_observer::setup_observers_for_all_layers(&mut state);
 186→
 187→        // Emit EnsureSync on page open to trigger remote subscription
 188→        // Flow: EnsureSync → Coordinator → (connect if needed) → RefreshSubscriptions → remote subscribes
 189→        // Works for both ToSource mode (single sync_target) and Broadcast mode (all authorized users)
 190→        if let Some(ref tx) = state.sync_event_tx {
 191→            let sync_targets = sync::reconcile::get_sync_targets(&state);
 192→            if sync_targets.is_empty() {
 193→                debug!(page_id = %state.page_id, "No sync targets on page open");
 194→            } else {
 195→                info!(page_id = %state.page_id, targets = ?sync_targets, "Emitting EnsureSync for {} targets on page open", sync_targets.len());
 196→                for user_did in sync_targets {
 197→                    let event = message::SyncEvent::EnsureSync {
 198→                        user_did: user_did.clone(),
 199→                    };
 200→                    state.emit_sync_event_capture(&event);
 201→                    match tx.try_send(event) {
 202→                        Ok(()) => info!(user_did = %user_did, page_id = %state.page_id, "Emitted EnsureSync on page open"),
 203→                        Err(e) => warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync on page open"),
 204→                    }
 205→                }
 206→            }
 207→        }
 208→
 209→        // Note: Node script spawning is handled by the caller (e.g., kunki's NodeRuntimeManager)
 210→        // This keeps the Scribe actor storage-agnostic and focused on CRDT sync
 211→
 212→        Ok(state)
 213→    }
 214→
 215→    #[instrument(level = "trace", skip_all, fields(page_id = %state.page_id))]
 216→    async fn handle(
 217→        &self,
 218→        myself: ActorRef<Self::Msg>,
 219→        message: Self::Msg,
 220→        state: &mut Self::State,
 221→    ) -> std::result::Result<(), ActorProcessingErr> {
 222→        match message {
 223→            ScribeMessage::Subscribe {
 224→                user_did,
 225→                device_id,
 226→                broadcast_tx,
 227→                ephemeral_tx,
 228→                permit,
 229→            } => {
 230→                sync::handle_subscribe(state, user_did, device_id, broadcast_tx, ephemeral_tx, permit).await;
 231→            }
 232→
 233→            ScribeMessage::Unsubscribe { user_did, device_id } => {
 234→                sync::handle_unsubscribe(state, &user_did, &device_id).await;
 235→            }
 236→
 237→            ScribeMessage::SubscribeToPageUpdates { tx } => {
 238→                // Send PeerSubscribed for all currently subscribed peers
 239→                // (peers that subscribed before this app opened)
 240→                if let Ok(subs) = state.subscribers.read() {
 241→                    info!(page_id = %state.page_id, peer_count = subs.len(), "Sending existing peers as PeerSubscribed");
 242→                    for ((user_did, _device_id), _info) in subs.iter() {
 243→                        let _ = tx.try_send(message::PageUpdate::PeerSubscribed {
 244→                            did: user_did.clone(),
 245→                            username: None,
 246→                        });
 247→                    }
 248→                }
 249→
 250→                // Presence state is delivered via CRDT sync (presence layer snapshot)
 251→                // No need to send OnlinePeers event — apps read from LayerChanged on {page_id}/presence
 252→
 253→                if let Ok(mut subs) = state.page_update_subscribers.write() {
 254→                    subs.push(tx);
 255→                    info!(page_id = %state.page_id, subscriber_count = subs.len(), "PageUpdate subscriber added");
 256→                }
 257→            }
 258→
 259→            ScribeMessage::ApplyUpdate {
 260→                layer_name,
 261→                update,
 262→                from_peer,
 263→                permit,
 264→            } => {
 265→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 266→                // Loro observer handles broadcast automatically after import()
 267→                let _ = sync::handle_apply_update(
 268→                    state,
 269→                    &layer_name,
 270→                    &update,
 271→                    from_peer,
 272→                    permit.as_deref(),
 273→                )
 274→                .await;
 275→            }
 276→
 277→            ScribeMessage::ApplyUpdateWithResult {
 278→                layer_name,
 279→                update,
 280→                from_peer,
 281→                permit,
 282→                reply,
 283→            } => {
 284→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 285→                // Loro observer handles broadcast automatically after import()
 286→                let result = sync::handle_apply_update(
 287→                    state,
 288→                    &layer_name,
 289→                    &update,
 290→                    from_peer,
 291→                    permit.as_deref(),
 292→                )
 293→                .await;
 294→                let _ = reply.send(result);
 295→            }
 296→
 297→            ScribeMessage::SyncRequest {
 298→                layer_name,
 299→                their_vector,
 300→                reply,
 301→            } => {
 302→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 303→                let result = sync::handle_sync_request(state, &layer_name, &their_vector);
 304→                let _ = reply.send(result);
 305→            }
 306→
 307→            ScribeMessage::ExportSnapshot { layer_name, reply } => {
 308→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 309→                let result = sync::handle_export_snapshot(state, &layer_name);
 310→                let _ = reply.send(result);
 311→            }
 312→
 313→            ScribeMessage::GetStateVector { layer_name, reply } => {
 314→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 315→                let result = sync::handle_get_state_vector(state, &layer_name);
 316→                let _ = reply.send(result);
 317→            }
 318→
 319→            ScribeMessage::GetUpdatesSince {
 320→                layer_name,
 321→                state_vector,
 322→                reply,
 323→            } => {
 324→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 325→                let result = sync::handle_get_updates_since(state, &layer_name, &state_vector);
 326→                let _ = reply.send(result);
 327→            }
 328→
 329→            ScribeMessage::ReplaceLayer {
 330→                layer_name,
 331→                snapshot,
 332→                reply,
 333→            } => {
 334→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 335→                let is_new = !state.units.contains_key(&layer_name);
 336→
 337→                // If the layer doesn't exist yet (sync_meta discovery → SyncReset),
 338→                // create it before replacing so observer + auth are set up.
 339→                if is_new {
 340→                    let mut unit = LayerUnit::new_empty();
 341→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
 342→                    state.units.insert(layer_name.clone(), unit);
 343→                    info!(layer = %layer_name, "Created new layer for snapshot replacement");
 344→                }
 345→
 346→                // Replace layer entirely with authoritative snapshot (SyncReset recovery)
 347→                info!(layer = %layer_name, snapshot_len = snapshot.len(), "Replacing layer with authoritative snapshot");
 348→                let result = match Layer::from_snapshot(&snapshot) {
 349→                    Ok(layer) => {
 350→                        if let Some(unit) = state.units.get_mut(&layer_name) {
 351→                            unit.replace_layer(layer);
 352→                            unit.mark_dirty();
 353→                        }
 354→                        info!(layer = %layer_name, "Layer replaced successfully");
 355→
 356→                        if is_new {
 357→                            // Authorize ALL existing subscribers for this new layer.
 358→                            // ReplaceLayer is called from SyncSnapshot (authoritative reset),
 359→                            // meaning the remote peer sent us this layer — all connected
 360→                            // peers should be able to receive our writes back.
 361→                            // can_receive_layer only checks the page permit (not layer permits),
 362→                            // so it fails for dynamic layers. Authorize unconditionally.
 363→                            if let Ok(subs) = state.subscribers.read() {
 364→                                for ((did, _), _info) in subs.iter() {
 365→                                    if let Some(unit) = state.units.get(&layer_name) {
 366→                                        unit.authorize_did(did);
 367→                                        info!(layer = %layer_name, did = %did, "Authorized subscriber for new ReplaceLayer");
 368→                                    }
 369→                                }
 370→                            }
 371→
 372→                            // Apply any pending authorizations
 373→                            if let Some(pending_dids) = state.pending_layer_authorizations.remove(&layer_name) {
 374→                                if let Some(unit) = state.units.get(&layer_name) {
 375→                                    for did in &pending_dids {
 376→                                        unit.authorize_did(did);
 377→                                        info!(layer = %layer_name, did = %did, "Applied pending layer authorization");
 378→                                    }
 379→                                }
 380→                            }
 381→
 382→                            // Set up Loro observer so future changes emit page_update events
 383→                            loro_observer::setup_layer_observer(state, &layer_name);
 384→
 385→                            // Notify UI about the discovered layer
 386→                            sync::broadcast::notify_layer_discovered(state, &layer_name);
 387→                        }
 388→
 389→                        Ok(())
 390→                    }
 391→                    Err(e) => {
 392→                        error!(layer = %layer_name, error = %e, "Failed to parse snapshot for layer replacement");
 393→                        Err(format!("Failed to parse snapshot: {}", e))
 394→                    }
 395→                };
 396→                let _ = reply.send(result);
 397→            }
 398→
 399→            ScribeMessage::Flush => {
 400→                sync::handle_flush(state).await;
 401→            }
 402→
 403→            ScribeMessage::EnsureLoroList { layer_name, reply } => {
 404→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 405→                // Get existing layer or create new one (for list access)
 406→                let is_new_layer = !state.units.contains_key(&layer_name);
 407→                if is_new_layer {
 408→                    let mut unit = LayerUnit::new_empty();
 409→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
 410→                    unit.mark_dirty();
 411→                    state.units.insert(layer_name.clone(), unit);
 412→                    debug!(layer = %layer_name, "Created new layer for Lua list");
 413→                    // Set up Loro observer for new layer to enable sync broadcasts
 414→                    loro_observer::setup_layer_observer(state, &layer_name);
 415→                    // Notify UI subscribers about the new layer
 416→                    sync::notify_layer_discovered(state, &layer_name);
 417→                }
 418→                // Just confirm the layer exists, don't return handle
 419→                let _ = reply.send(Ok(()));
 420→            }
 421→
 422→            ScribeMessage::EnsureLoroMap { layer_name, reply } => {
 423→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 424→                // Get existing layer or create new one (for map access)
 425→                let is_new_layer = !state.units.contains_key(&layer_name);
 426→                if is_new_layer {
 427→                    let mut unit = LayerUnit::new_empty();
 428→                    unit.set_local_only(!state.should_sync_layer(&layer_name));
 429→                    unit.mark_dirty();
 430→                    state.units.insert(layer_name.clone(), unit);
 431→                    debug!(layer = %layer_name, "Created new layer for Lua map");
 432→                    // Set up Loro observer for new layer to enable sync broadcasts
 433→                    loro_observer::setup_layer_observer(state, &layer_name);
 434→                }
 435→                // Just confirm the layer exists, don't return handle
 436→                let _ = reply.send(Ok(()));
 437→            }
 438→
 439→            ScribeMessage::LayerExists { layer_name, reply } => {
 440→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 441→                let exists = state.units.contains_key(&layer_name);
 442→                let _ = reply.send(exists);
 443→            }
 444→
 445→            // Typed read operations (for Lua bindings - avoids stale handles)
 446→
 447→            ScribeMessage::ListGet { layer_name, index, reply } => {
 448→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 449→                let result = state.units.get(&layer_name)
 450→                    .map(|unit| unit.layer())
 451→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
 452→                    .map(|layer| {
 453→                        let list = layer.loro().get_list(layer_name.clone());
 454→                        list.get(index).map(|v| {
 455→                            let deep = v.get_deep_value();
 456→                            domains::loro_value_to_json(deep)
 457→                        })
 458→                    });
 459→                let _ = reply.send(result);
 460→            }
 461→
 462→            ScribeMessage::ListLength { layer_name, reply } => {
 463→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 464→                let result = state.units.get(&layer_name)
 465→                    .map(|unit| unit.layer())
 466→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
 467→                    .map(|layer| {
 468→                        let list = layer.loro().get_list(layer_name.clone());
 469→                        list.len()
 470→                    });
 471→                let _ = reply.send(result);
 472→            }
 473→
 474→            ScribeMessage::MapGet { layer_name, key, reply } => {
 475→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 476→                let result = state.units.get(&layer_name)
 477→                    .map(|unit| unit.layer())
 478→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
 479→                    .map(|layer| {
 480→                        let map = layer.loro().get_map(layer_name.clone());
 481→                        map.get(&key).map(|v| {
 482→                            let deep = v.get_deep_value();
 483→                            domains::loro_value_to_json(deep)
 484→                        })
 485→                    });
 486→                let _ = reply.send(result);
 487→            }
 488→
 489→            ScribeMessage::MapLength { layer_name, reply } => {
 490→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 491→                let result = state.units.get(&layer_name)
 492→                    .map(|unit| unit.layer())
 493→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
 494→                    .map(|layer| {
 495→                        let map = layer.loro().get_map(layer_name.clone());
 496→                        map.len()
 497→                    });
 498→                let _ = reply.send(result);
 499→            }
 500→
 501→            ScribeMessage::MapKeys { layer_name, reply } => {
 502→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 503→                let result = state.units.get(&layer_name)
 504→                    .map(|unit| unit.layer())
 505→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.clone()))
 506→                    .map(|layer| {
 507→                        let map = layer.loro().get_map(layer_name.clone());
 508→                        map.keys().map(|k| k.to_string()).collect()
 509→                    });
 510→                let _ = reply.send(result);
 511→            }
 512→
 513→            ScribeMessage::ListLayers { pattern, reply } => {
 514→                let pattern = normalize_layer_name(&pattern, &state.page_id);
 515→                // Match layer names against glob pattern
 516→                let matching: Vec<String> = state
 517→                    .units
 518→                    .keys()
 519→                    .filter(|name| glob_match(&pattern, name))
 520→                    .cloned()
 521→                    .collect();
 522→                let _ = reply.send(matching);
 523→            }
 524→
 525→
 526→            ScribeMessage::GetLayerData { layer_name, reply } => {
 527→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 528→                let result = state.units.get(&layer_name)
 529→                    .map(|unit| unit.layer().get_content(&layer_name))
 530→                    .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()));
 531→                let _ = reply.send(result);
 532→            }
 533→
 534→            ScribeMessage::UpdatePeerVector {
 535→                user_did,
 536→                device_id,
 537→                layer_name,
 538→                state_vector,
 539→            } => {
 540→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 541→                if let Ok(mut subs) = state.subscribers.write() {
 542→                    if let Some(info) = subs.get_mut(&(user_did.clone(), device_id.clone())) {
 543→                        info.vectors.insert(layer_name.clone(), state_vector);
 544→                        trace!(user_did = %user_did, device_id = %device_id, layer_name = %layer_name, "Updated in-memory peer vector");
 545→                    }
 546→                }
 547→            }
 548→
 549→            ScribeMessage::ReconcileWithPeers => {
 550→                sync::handle_reconcile_with_peers(state).await;
 551→            }
 552→
 553→            ScribeMessage::GetSnapshot { layer_name, reply } => {
 554→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 555→                let result = state.units.get(&layer_name).map(|unit| unit.layer().export_snapshot());
 556→                let _ = reply.send(result);
 557→            }
 558→
 559→            ScribeMessage::GetLayerJson { layer_name, reply } => {
 560→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 561→                let result = state.units.get(&layer_name).map(|unit| unit.layer().get_content(&layer_name));
 562→                let _ = reply.send(result);
 563→            }
 564→
 565→            ScribeMessage::GetContext { reply } => {
 566→                let result = query::build_context_json(state);
 567→                let _ = reply.send(result);
 568→            }
 569→
 570→            ScribeMessage::Query { spec, reply } => {
 571→                let result = query::handle_query(state, &spec);
 572→                let _ = reply.send(result);
 573→            }
 574→
 575→            ScribeMessage::SubscribeQuery { spec, delta_tx } => {
 576→                query::handle_subscribe_query(state, spec, delta_tx).await;
 577→            }
 578→
 579→            ScribeMessage::UnsubscribeQuery { query_id } => {
 580→                state.query_subscribers.remove(&query_id);
 581→                debug!(page_id = %state.page_id, query_id = %query_id, "Query subscription removed");
 582→            }
 583→
 584→            ScribeMessage::UpdateFromJson {
 585→                layer_name,
 586→                path,
 587→                value,
 588→                reply,
 589→            } => {
 590→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 591→                let result = self
 592→                    .handle_update_from_json(state, &layer_name, &path, value)
 593→                    .await;
 594→                if let Some(tx) = reply {
 595→                    let _ = tx.send(result);
 596→                }
 597→            }
 598→
 599→            // Typed CRDT operations
 600→            // NOTE: Broadcast handled by Loro observer after commit() in each operation
 601→            ScribeMessage::ListPush {
 602→                layer_name,
 603→                path,
 604→                item,
 605→            } => {
 606→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 607→                if let Err(e) = operations::handle_list_push(state, &layer_name, &path, item).await {
 608→                    warn!(error = %e, "ListPush failed");
 609→                }
 610→            }
 611→
 612→            ScribeMessage::ListInsert {
 613→                layer_name,
 614→                path,
 615→                index,
 616→                item,
 617→            } => {
 618→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 619→                if let Err(e) = operations::handle_list_insert(state, &layer_name, &path, index, item).await {
 620→                    warn!(error = %e, "ListInsert failed");
 621→                }
 622→            }
 623→
 624→            ScribeMessage::ListDelete {
 625→                layer_name,
 626→                path,
 627→                index,
 628→            } => {
 629→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 630→                if let Err(e) = operations::handle_list_delete(state, &layer_name, &path, index).await {
 631→                    warn!(error = %e, "ListDelete failed");
 632→                }
 633→            }
 634→
 635→            ScribeMessage::MapInsert {
 636→                layer_name,
 637→                path,
 638→                key,
 639→                value,
 640→            } => {
 641→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 642→                if let Err(e) = operations::handle_map_insert(state, &layer_name, &path, &key, value).await {
 643→                    warn!(error = %e, "MapInsert failed");
 644→                }
 645→            }
 646→
 647→            ScribeMessage::MapDelete {
 648→                layer_name,
 649→                path,
 650→                key,
 651→            } => {
 652→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 653→                if let Err(e) = operations::handle_map_delete(state, &layer_name, &path, &key).await {
 654→                    warn!(error = %e, "MapDelete failed");
 655→                }
 656→            }
 657→
 658→            ScribeMessage::CounterInc {
 659→                layer_name,
 660→                path,
 661→                amount,
 662→            } => {
 663→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
 664→                if let Err(e) = operations::handle_counter_inc(state, &layer_name, &path, amount).await {
 665→                    warn!(error = %e, "CounterInc failed");
 666→                }
 667→            }
 668→
 669→            ScribeMessage::CreateDynamicLayer { schema_key, layer_id, reply } => {
 670→                let result = crate::layer_unit::handle_create_dynamic_layer(
 671→                    state, &schema_key, &layer_id,
 672→                );
 673→                let _ = reply.send(result);
 674→            }
 675→
 676→            ScribeMessage::AddLayerAccess { layer_name, did, reply } => {
 677→                let result = crate::layer_unit::handle_add_layer_access(state, &layer_name, &did).await;
 678→                if let Err(ref e) = result {
 679→                    warn!(
 680→                        page_id = %state.page_id,
 681→                        layer = %layer_name,
 682→                        did = %did,
 683→                        error = %e,
 684→                        "AddLayerAccess failed"
 685→                    );
 686→                }
 687→                let _ = reply.send(result);
 688→            }
 689→
 690→            ScribeMessage::RemoveLayerAccess { layer_name, did, reply } => {
 691→                let result = crate::layer_unit::handle_remove_layer_access(state, &layer_name, &did);
 692→                let _ = reply.send(result);
 693→            }
 694→
 695→            ScribeMessage::AuthorizeLayerSubscriber { layer_name, subscriber_did } => {
 696→                let bare = normalize_layer_name(&layer_name, &state.page_id);
 697→                if let Some(unit) = state.units.get(&bare) {
 698→                    unit.authorize_did(&subscriber_did);
 699→                    state.emit_layer_auth_capture(&bare, &subscriber_did, "authorized");
 700→                    info!(layer = %bare, did = %subscriber_did, "Authorized subscriber for layer");
 701→                } else {
 702→                    // Layer doesn't exist yet — store pending authorization
 703→                    state.pending_layer_authorizations
 704→                        .entry(bare.clone())
 705→                        .or_insert_with(Vec::new)
 706→                        .push(subscriber_did.clone());
 707→                    // Emit with pending_count showing queue size
 708→                    let pending_count = state.pending_layer_authorizations
 709→                        .get(&bare).map(|v| v.len()).unwrap_or(0);
 710→                    if let Some(ref tx) = state.capture_tx {
 711→                        let ts = std::time::SystemTime::now()
 712→                            .duration_since(std::time::UNIX_EPOCH)
 713→                            .map(|d| d.as_millis())
 714→                            .unwrap_or(0);
 715→                        if let Ok(json) = serde_json::to_string(&serde_json::json!({
 716→                            "type": "layer_auth",
 717→                            "ts": ts,
 718→                            "seq": state.capture_seq.fetch_add(1, std::sync::atomic::Ordering::Relaxed),
 719→                            "page_id": &state.page_id,
 720→                            "layer": &bare,
 721→                            "layer_short": crate::state::layer_short(&bare),
 722→                            "did": &subscriber_did,
 723→                            "short_did": crate::state::short_did(&subscriber_did),
 724→                            "action": "pending",
 725→                            "pending_count": pending_count,
 726→                        })) {
 727→                            let _ = tx.send(json);
 728→                        }
 729→                    }
 730→                    info!(layer = %bare, did = %subscriber_did, pending_count = pending_count, "Stored pending layer authorization (layer not yet created)");
 731→                }
 732→            }
 733→
 734→            ScribeMessage::Shutdown => {
 735→                info!(page_id = %state.page_id, "Scribe shutting down");
 736→                sync::handle_flush(state).await;
 737→                myself.stop(Some("shutdown".to_string()));
 738→            }
 739→
 740→            // Ephemeral events (from datagrams via PeerActor)
 741→            ScribeMessage::RemoteEphemeral { user_did, device_id, payload } => {
 742→                // Log payload content for debugging
 743→                let payload_str = std::str::from_utf8(&payload).unwrap_or("<binary>");
 744→                debug!(
 745→                    page_id = %state.page_id,
 746→                    user_did = ?user_did,
 747→                    device_id = ?device_id,
 748→                    payload_len = payload.len(),
 749→                    payload = %payload_str,
 750→                    our_did = %state.our_did,
 751→                    "Scribe received RemoteEphemeral"
 752→                );
 753→                // 1. Forward to local app layer (if we have sender info)
 754→                if let Some(ref did) = user_did {
 755→                    let handled = route_remote_ephemeral(state, did, &payload);
 756→                    debug!(page_id = %state.page_id, handled = handled, our_did = %state.our_did, "route_remote_ephemeral returned");
 757→                    if !handled {
 758→                        let dev_id = device_id.as_deref().unwrap_or_default();
 759→                        emit_raw_ephemeral(state, did, dev_id, &payload);
 760→                    }
 761→                } else {
 762→                    debug!(page_id = %state.page_id, "RemoteEphemeral without user_did - not emitting to local app");
 763→                }
 764→
 765→                // 2. Relay to other subscribers (node mode relay) - exclude sender
 766→                let exclude = match (&user_did, &device_id) {
 767→                    (Some(d), Some(dev)) => Some((d.as_str(), dev.as_str())),
 768→                    _ => None,
 769→                };
 770→                broadcast_ephemeral_to_subscribers(state, &payload, exclude);
 771→            }
 772→
 773→            ScribeMessage::SendEphemeral { payload } => {
 774→                // Broadcast ephemeral data directly to all subscribed PeerActors
 775→                // No exclusion - this is local user action, send to everyone
 776→                debug!(page_id = %state.page_id, payload_len = payload.len(), "Broadcasting ephemeral to all subscribers");
 777→                broadcast_ephemeral_to_subscribers(state, &payload, None);
 778→            }
 779→
 780→            ScribeMessage::SendStructuredEphemeral { func, args } => {
 781→                // Log the incoming request
 782→                let has_permit = state.our_permit.is_some();
 783→                let ephemeral_funcs = state.our_permit
 784→                    .as_ref()
 785→                    .map(|p| p.ephemeral_funcs().to_vec())
 786→                    .unwrap_or_default();
 787→                debug!(
 788→                    page_id = %state.page_id,
 789→                    func = %func,
 790→                    has_permit = has_permit,
 791→                    ephemeral_funcs = ?ephemeral_funcs,
 792→                    our_did = %state.our_did,
 793→                    "SendStructuredEphemeral received"
 794→                );
 795→
 796→                // Validate func against our permit's ephemeral_funcs (if set)
 797→                // Empty ephemeral_funcs list means all funcs allowed
 798→                let can_send = state.our_permit
 799→                    .as_ref()
 800→                    .map(|p| p.can_send_ephemeral(&func))
 801→                    .unwrap_or(true); // No permit = allow (local mode)
 802→
 803→                if !can_send {
 804→                    warn!(page_id = %state.page_id, func = %func, "Structured ephemeral func not allowed by permit");
 805→                    return Ok(());
 806→                }
 807→
 808→                // Broadcast as StructuredEphemeral to app subscribers (local UI)
 809→                let our_did = state.our_did.clone();
 810→                emit_structured_ephemeral(state, &our_did, &func, &args);
 811→
 812→                // Also broadcast via ephemeral channel for remote peers
 813→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
 814→                // Include from_did so relayed messages preserve original sender identity
 815→                let payload = serde_json::json!({
 816→                    "type": "structured",
 817→                    "from_did": our_did,
 818→                    "func": func,
 819→                    "args": args
 820→                });
 821→                if let Ok(bytes) = serde_json::to_vec(&payload) {
 822→                    debug!(
 823→                        page_id = %state.page_id,
 824→                        func = %func,
 825→                        "Broadcasting structured ephemeral to PeerActor subscribers"
 826→                    );
 827→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
 828→                }
 829→            }
 830→
 831→            ScribeMessage::RemoteStructuredEphemeral { from_did, device_id, func, args } => {
 832→                // Validate func against sender's permit
 833→                let can_send = {
 834→                    let subs = state.subscribers.read().ok();
 835→                    subs.and_then(|s| {
 836→                        s.get(&(from_did.clone(), device_id.clone()))
 837→                            .map(|info| info.permit.can_send_ephemeral(&func))
 838→                    }).unwrap_or(false) // Unknown sender = reject
 839→                };
 840→
 841→                if !can_send {
 842→                    warn!(
 843→                        page_id = %state.page_id,
 844→                        from_did = %from_did,
 845→                        func = %func,
 846→                        "Remote structured ephemeral rejected - func not allowed"
 847→                    );
 848→                    return Ok(());
 849→                }
 850→
 851→                // Emit to local app subscribers
 852→                emit_structured_ephemeral(state, &from_did, &func, &args);
 853→
 854→                debug!(
 855→                    page_id = %state.page_id,
 856→                    from_did = %from_did,
 857→                    func = %func,
 858→                    "Processed remote structured ephemeral"
 859→                );
 860→            }
 861→
 862→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
 863→
 864→            // Derivation operations (now handled by kunki/LuaRuntime externally)
 865→            ScribeMessage::RebuildDerived { target: _, reply } => {
 866→                // Derivation is now handled by kunki, not Scribe
 867→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 868→            }
 869→
 870→            ScribeMessage::RebuildAllDerived { reply } => {
 871→                // Derivation is now handled by kunki, not Scribe
 872→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 873→            }
 874→
 875→            ScribeMessage::IsDerivationEnabled { reply } => {
 876→                // Derivation is now external, Scribe always returns false
 877→                let _ = reply.send(false);
 878→            }
 879→
 880→            ScribeMessage::CreateDerivedLayer { target_layer } => {
 881→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
 882→                // Create the derived layer (empty) so it exists for subscribers
 883→                if !state.units.contains_key(&target_layer) {
 884→                    let unit = LayerUnit::new_empty();
 885→                    let _ = unit.layer().loro().get_map(target_layer.clone());
 886→                    unit.layer().commit();
 887→                    state.units.insert(target_layer.clone(), unit);
 888→                    info!(target = %target_layer, "Created empty derived layer");
 889→
 890→                    // Set up observer for the new layer
 891→                    loro_observer::setup_layer_observer(state, &target_layer);
 892→                }
 893→            }
 894→
 895→            ScribeMessage::GetAppFiles { app_name, reply } => {
 896→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
 897→                let layer_name = format!("app:{}", app_name);
 898→                let result = if let Some(unit) = state.units.get(&layer_name) {
 899→                    Ok(unit.layer().get_all_files())
 900→                } else {
 901→                    Err(format!("App layer '{}' not found", layer_name))
 902→                };
 903→                let _ = reply.send(result);
 904→            }
 905→
 906→            ScribeMessage::GetSubscriberCount { reply } => {
 907→                let count = state.subscribers.read()
 908→                    .map(|s| s.len())
 909→                    .unwrap_or(0);
 910→                let _ = reply.send(count);
 911→            }
 912→
 913→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
 914→                // RefreshApp requires filesystem access which is handled by butler's refresh service
 915→                // This stub returns an error - callers should use butler's refresh functionality instead
 916→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
 917→            }
 918→        }
 919→
 920→        Ok(())
 921→    }
 922→
 923→    #[instrument(skip_all, fields(page_id = %state.page_id))]
 924→    async fn post_stop(
 925→        &self,
 926→        _myself: ActorRef<Self::Msg>,
 927→        state: &mut Self::State,
 928→    ) -> std::result::Result<(), ActorProcessingErr> {
 929→        // Flush any dirty layers before stopping
 930→        let has_dirty = state.units.values().any(|u| u.is_dirty());
 931→        if has_dirty {
 932→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
 933→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
 934→            sync::handle_flush(state).await;
 935→        }
 936→
 937→        // Stop node script if running
 938→        if let Some(tx) = state.node_script_shutdown.take() {
 939→            info!(page_id = %state.page_id, "Stopping node script tick loop");
 940→            let _ = tx.send(()).await;
 941→        }
 942→
 943→        info!(page_id = %state.page_id, "Scribe stopped");
 944→        Ok(())
 945→    }
 946→}
 947→
 948→// Helper Methods
 949→
 950→impl Scribe {
 951→    /// Handle JSON update from UI (CEL commit())
 952→    ///
 953→    /// **Broadcast**: Handled automatically by Loro observer after commit()
 954→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
 955→    async fn handle_update_from_json(
 956→        &self,
 957→        state: &mut ScribeState,
 958→        layer_name: &str,
 959→        path: &str,
 960→        value: serde_json::Value,
 961→    ) -> Result<()> {
 962→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
 963→
 964→        // Get or create the layer unit
 965→        let unit = state
 966→            .units
 967→            .entry(layer_name.to_string())
 968→            .or_insert_with(LayerUnit::new_empty);
 969→
 970→        // Convert JSON to Loro and update
 971→        unit.layer()
 972→            .set_from_json(path, &value)
 973→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
 974→
 975→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
 976→        unit.layer().commit();
 977→
 978→        // Mark as dirty for persistence
 979→        unit.mark_dirty();
 980→
 981→        debug!("Layer update from JSON complete, observer will broadcast");
 982→        Ok(())
 983→    }
 984→}
 985→
 986→// Tests
 987→
 988→#[cfg(test)]
 989→mod tests {
 990→    use super::*;
 991→    use crate::test_fixtures::node_scribe_args;
 992→    use std::time::Duration;
 993→
 994→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
 995→    #[tokio::test]
 996→    async fn test_ephemeral_with_no_subscribers() {
 997→        let args = node_scribe_args("test-page-456");
 998→        let (scribe_ref, _handle) = ractor::Actor::spawn(
 999→            Some("test-scribe-no-subs".to_string()),
1000→            Scribe,
1001→            args,
1002→        ).await.expect("Failed to spawn Scribe");
1003→
1004→        // Send ephemeral with no subscribers - should not crash
1005→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
1006→            func: "typing".to_string(),
1007→            args: serde_json::json!({"user": "TestUser"}),
1008→        }).expect("Failed to send ephemeral");
1009→
1010→        // Small delay to ensure message is processed
1011→        tokio::time::sleep(Duration::from_millis(50)).await;
1012→
1013→        println!("✓ Ephemeral with no subscribers handled gracefully");
1014→        scribe_ref.stop(Some("test complete".to_string()));
1015→    }
1016→}
