402→impl<C: Connection> Coordinator<C> {
403→    /// Handle new connection - spawn PeerActor with permit if outbound
404→    #[instrument(skip_all, fields(node_id = %node_id))]
405→    async fn on_connected(
406→        &self,
407→        myself: ActorRef<CoordinatorMessage<C>>,
408→        node_id: NodeId,
409→        conn: C,
410→        state: &mut CoordinatorState<C>,
411→    ) {
412→        info!("New connection from: {}", node_id);
413→
414→        // Check if this was an outbound connection WE initiated - get permit if so
415→        let is_outbound = state.pending_connections.remove(&node_id);
416→        let permit = if is_outbound {
417→            state.pending_permits.remove(&node_id)
418→        } else {
419→            None
420→        };
421→
422→        if is_outbound && permit.is_none() {
423→            warn!("Outbound connection to {} but no permit - cannot handshake", node_id);
424→        }
425→
426→        // Spawn PeerActor - if permit provided, it auto-initiates handshake
427→        let peer_actor = PeerActor::<C>::new(node_id);
428→        let args = PeerActorArgs {
429→            mode: state.mode,
430→            conn: conn.clone(),
431→            coordinator: myself.clone(),
432→            butler: state.butler.clone(),
433→            blob_store: state.blob_store.clone(),
434→            permit,
435→            message_tx: state.message_tx.clone(),
436→            our_node_id: state.our_node_id,
437→            capture_tx: state.capture_tx.clone(),
438→        };
439→
440→        match Actor::spawn_linked(None, peer_actor, args, myself.get_cell()).await {
441→            Ok((actor_ref, _)) => {
442→                state.add_peer(node_id, actor_ref, conn);
443→                debug!("PeerActor spawned for {}", node_id);
444→            }
445→            Err(e) => {
446→                error!("Failed to spawn PeerActor for {}: {:?}", node_id, e);
447→            }
448→        }
449→    }
450→
451→    /// Handle disconnection - cleanup peer state and emit event
452→    #[instrument(skip_all, fields(node_id = %node_id))]
453→    async fn on_disconnected(&self, node_id: NodeId, state: &mut CoordinatorState<C>) {
454→        info!("Disconnected: {}", node_id);
455→
456→        if let Some(entry) = state.peers.remove(&node_id) {
457→            entry.actor.stop(Some("disconnected".to_string()));
458→        }
459→
460→        state.pending_connections.remove(&node_id);
461→        state.pending_permits.remove(&node_id);
462→
463→        // Emit disconnect event for app layer
464→        Self::emit_event(state, CourierEvent::PeerDisconnected {
465→            node_id: node_id.to_string(),
466→        });
467→    }
468→
469→    /// Connect to peer (fire-and-forget, result via events)
470→    ///
471→    /// **Context**: App calls connect(), we store permit and mark as pending
472→    /// **Transport**: CourierRunner sees pending_connections and calls transport.connect()
473→    /// **Events**: PeerAuthenticated on success, ConnectionFailed on failure
474→    #[instrument(skip_all, fields(node_id = %node_id))]
475→    async fn on_connect(
476→        &self,
477→        node_id: NodeId,
478→        permit: String,
479→        state: &mut CoordinatorState<C>,
480→    ) {
481→        info!("Connect: node={}", node_id);
482→
483→        // Check if already authenticated - emit event immediately
484→        if state.is_authenticated(&node_id) {
485→            info!("Peer {} already authenticated", node_id);
486→            if let Some(auth) = state.get_auth(&node_id) {
487→                Self::emit_event(state, CourierEvent::PeerAuthenticated {
488→                    node_id: node_id.to_string(),
489→                    did: auth.did.clone(),
490→                    username: auth.username.clone(),
491→                });
492→            }
493→            return;
494→        }
495→
496→        // Check if already connected - initiate handshake with existing PeerActor
497→        if let Some(actor) = state.get_actor(&node_id).cloned() {
498→            info!("Peer {} already connected - initiating handshake", node_id);
499→            if let Err(e) = actor.cast(PeerMessage::InitiateHandshake { permit }) {
500→                warn!("Failed to send InitiateHandshake to {}: {:?}", node_id, e);
501→            }
502→            return;
503→        }
504→
505→        // Mark as pending outbound connection and store permit
506→        state.pending_connections.insert(node_id);
507→        state.pending_permits.insert(node_id, permit.clone());
508→
509→        // Request transport connection via CourierRunner
510→        if let Some(ref tx) = state.connect_tx {
511→            if let Err(e) = tx.try_send(ConnectRequest { node_id, permit }) {
512→                warn!(node_id = %node_id, error = %e, "Failed to send connect request");
513→                Self::emit_event(state, CourierEvent::ConnectionFailed {
514→                    node_id: node_id.to_string(),
515→                    error: format!("Failed to initiate connection: {}", e),
516→                });
517→            }
518→        }
519→    }
520→
521→    /// Handle EnsureSync from Scribe - connect to user if not already connected
522→    #[instrument(skip_all, fields(user_did = %user_did))]
523→    async fn on_ensure_sync(
524→        &self,
525→        _myself: ActorRef<CoordinatorMessage<C>>,
526→        user_did: String,
527→        state: &mut CoordinatorState<C>,
528→    ) {
529→        info!(user_did = %user_did, "Scribe requested sync with user");
530→
531→        // Check if user is already connected
532→        if let Some(peer_actor) = self.get_peer_actor_for_user(&user_did, state) {
533→            info!(user_did = %user_did, "User already connected, sending RefreshSubscriptions to PeerActor");
534→            let _ = peer_actor.cast(PeerMessage::RefreshSubscriptions);
535→            return;
536→        }
537→
538→        // Resolve user_did to device info
539→        let device_info = match state.butler.contacts().resolve_device(&user_did) {
540→            Ok(Some(info)) => info,
541→            Ok(None) => {
542→                // In Node mode, viewers initiate connections - we don't reconnect to them
543→                // This is expected behavior, not a warning condition
544→                if state.mode == CourierMode::Node {
545→                    debug!(user_did = %user_did, "Viewer not connected (will reconnect when online)");
546→                } else {
547→                    warn!(user_did = %user_did, "No device info found for user");
548→                }
549→                return;
550→            }
551→            Err(e) => {
552→                warn!(user_did = %user_did, error = %e, "Failed to resolve device");
553→                return;
554→            }
555→        };
556→
557→        let node_id = match device_info.node_id.parse::<NodeId>() {
558→            Ok(id) => id,
559→            Err(e) => {
560→                warn!(node_id = %device_info.node_id, error = ?e, "Failed to parse node_id");
561→                return;
562→            }
563→        };
564→
565→        // Check if already connecting/connected
566→        if state.is_connected(&node_id) || state.pending_connections.contains(&node_id) {
567→            debug!(user_did = %user_did, node_id = %node_id, "Already connected/connecting");
568→            return;
569→        }
570→
571→        info!(user_did = %user_did, node_id = %node_id, "Requesting connection for sync");
572→
573→        state.pending_connections.insert(node_id);
574→        state.pending_permits.insert(node_id, device_info.permit.clone());
575→
576→        if let Some(ref tx) = state.connect_tx {
577→            if let Err(e) = tx.try_send(ConnectRequest {
578→                node_id,
579→                permit: device_info.permit.clone(),
580→            }) {
581→                warn!(node_id = %node_id, error = %e, "Failed to send connect request");
582→            }
583→        }
584→
585→        Self::emit_event(state, CourierEvent::ConnectRequested {
586→            node_id: node_id.to_string(),
587→            permit: device_info.permit,
588→        });
589→    }
590→
591→    /// Find peer actor for a user by DID
592→    fn get_peer_actor_for_user<'a>(
593→        &self,
594→        user_did: &str,
595→        state: &'a CoordinatorState<C>,
596→    ) -> Option<&'a ActorRef<PeerMessage>> {
597→        state.authenticated_peers()
598→            .find(|(_, entry)| entry.auth.as_ref().map(|a| a.did.as_str()) == Some(user_did))
599→            .map(|(_, entry)| &entry.actor)
600→    }
601→
602→    /// Distribute layer permits for a new dynamic layer (Node mode)
603→    ///
604→    /// **Context**: Scribe detected new dynamic layer, permits already created by layer_unit
605→    /// **We do**: Store each permit in butler, send LayerPermitMsg to each recipient's PeerActor
606→    #[instrument(skip_all, fields(page_id = %page_id, layer = %layer_name, permit_count = permits.len()))]
607→    async fn on_distribute_layer_permits(
608→        &self,
609→        page_id: &str,
610→        layer_name: &str,
611→        permits: &[(String, String)],
612→        state: &mut CoordinatorState<C>,
613→    ) {
614→        info!(
615→            "Distributing {} layer permits for page={} layer={}",
616→            permits.len(), page_id, layer_name
617→        );
618→
619→        for (recipient_did, permit_token) in permits {
620→            // Store layer permit in butler
621→            if let Err(e) = state.butler.permits().store_layer_permit(
622→                page_id,
623→                recipient_did,
624→                layer_name,
625→                permit_token,
626→            ) {
627→                warn!(
628→                    recipient = %recipient_did,
629→                    error = %e,
630→                    "Failed to store layer permit"
631→                );
632→                continue;
633→            }
634→
635→            // Find PeerActor for this recipient and send
636→            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
637→                if let Err(e) = actor.cast(PeerMessage::SendLayerPermit {
638→                    page_id: page_id.to_string(),
639→                    layer_name: layer_name.to_string(),
640→                    permit: permit_token.clone(),
641→                }) {
642→                    warn!(
643→                        recipient = %recipient_did,
644→                        error = %e,
645→                        "Failed to send LayerPermit to PeerActor"
646→                    );
647→                } else {
648→                    info!(recipient = %recipient_did, "Sent LayerPermit to PeerActor");
649→                }
650→            } else {
651→                // Peer not connected — permit stored, will be sent on reconnect
652→                debug!(
653→                    recipient = %recipient_did,
654→                    "Peer not connected, layer permit stored for reconnect"
655→                );
656→            }
657→        }
658→    }
659→
660→    /// Distribute updated page permits after reissue (Node mode)
661→    ///
662→    /// **Context**: New app installed → page permits reissued with new layers
663→    /// **We do**: Store updated permits in butler, send PermitUpdate to each recipient
664→    #[instrument(skip_all, fields(page_id = %page_id, permit_count = permits.len()))]
665→    async fn on_distribute_page_permit_updates(
666→        &self,
667→        page_id: &str,
668→        permits: &[(String, String)],
669→        state: &mut CoordinatorState<C>,
670→    ) {
671→        info!(
672→            "Distributing {} page permit updates for page={}",
673→            permits.len(), page_id
674→        );
675→
676→        for (recipient_did, permit_token) in permits {
677→            // Store updated permit in butler
678→            if let Err(e) = state.butler.permits().store_page_permit(
679→                page_id,
680→                recipient_did,
681→                permit_token,
682→            ) {
683→                warn!(
684→                    recipient = %recipient_did,
685→                    error = %e,
686→                    "Failed to store updated page permit"
687→                );
688→                continue;
689→            }
690→
691→            // Find PeerActor for this recipient and send
692→            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
693→                if let Err(e) = actor.cast(PeerMessage::SendPermitUpdate {
694→                    page_id: page_id.to_string(),
695→                    permit: permit_token.clone(),
696→                }) {
697→                    warn!(
698→                        recipient = %recipient_did,
699→                        error = %e,
700→                        "Failed to send PermitUpdate to PeerActor"
701→                    );
702→                } else {
703→                    info!(recipient = %recipient_did, "Sent PermitUpdate to PeerActor");
704→                }
705→            } else {
706→                // Peer not connected — permit stored, will be picked up on reconnect
707→                debug!(
708→                    recipient = %recipient_did,
709→                    "Peer not connected, updated page permit stored for reconnect"
710→                );
711→            }
712→        }
713→    }
714→
715→    /// Handle page opened - refresh subscriptions for all authenticated peers
716→    ///
717→    /// **Context**: App opened a page, subscriptions may not be established yet
718→    /// **We do**: Send RefreshSubscriptions to all authenticated PeerActors
719→    /// **Design**: Ensures subscription after page open (race condition fix)
720→    #[instrument(skip_all, fields(page_id = %page_id))]
721→    async fn on_page_opened(&self, page_id: &str, state: &mut CoordinatorState<C>) {
722→        let peer_count = state.authenticated_peers().count();
723→        if peer_count == 0 {
724→            debug!(page_id = %page_id, "No authenticated peers to refresh subscriptions for");
725→            return;
726→        }
727→
728→        info!(page_id = %page_id, peer_count = peer_count, "Page opened, refreshing subscriptions for authenticated peers");
729→
730→        for (node_id, entry) in state.authenticated_peers() {
731→            if let Err(e) = entry.actor.cast(PeerMessage::RefreshSubscriptions) {
732→                warn!(node_id = %node_id, error = %e, "Failed to send RefreshSubscriptions");
733→            }
734→        }
735→    }
736→}
