-- Collection of demo apps showcasing different features
page("Demos", "1.0.0")

-- =============================================================================
-- Roles
-- =============================================================================

-- Owner: Full control over all demos
role("owner", {
    can_share = true,
    can_delegate = true
})

-- Collaborator: Can participate in demos
role("collaborator", {
    parent = "owner"
})

-- Node: Relay for multiplayer demos
role("node", {
    parent = "owner",
    can_relay = true
})

-- =============================================================================
-- Layers
-- =============================================================================

