    #[test]
    fn test_validate_creator_namespace() {
        assert!(validate_creator_namespace(
            "page1/channels/did:key:alice/general/messages",
            "page1",
            "did:key:alice",
        ));
        // Wrong DID
        assert!(!validate_creator_namespace(
            "page1/channels/did:key:alice/general/messages",
            "page1",
            "did:key:bob",
        ));
        // Bare path (no page prefix)
        assert!(validate_creator_namespace(
            "channels/did:key:alice/general/messages",
            "other_page",
