            .write()
            .expect("subscriber lock poisoned")
            .insert(("did:key:alice".to_string(), "device1".to_string()), subscriber);

        let mut role_permissions = HashMap::new();
        role_permissions.insert(
            "node_viewer".to_string(),
            gurkha::LayerConfig {
                sync: true,
                write: false,
                layer_type: None,
