 1→//! Permit Token Builder - Execution Layer
 2→//!
 3→//! Separates "what to build" (TokenDecision) from "how to build" (GurkhaPermitBuilder).
 4→//! This layer handles the actual token construction with automatic proof chain handling.
 5→
 6→use crate::crypto::sign_permit;
 7→use crate::decision::TokenDecision;
 8→use crate::errors::GurkhaError;
 9→use tracing::{debug, info};
10→
11→/// Builder for constructing permit tokens from decisions
12→///
13→/// This execution layer takes a TokenDecision (pure logic) and builds the actual
14→/// token with automatic proof chain handling.
15→///
16→/// # Example
17→/// ```ignore
18→/// let secret_key: [u8; 32] = identity.secret_signing_key();
19→/// let builder = GurkhaPermitBuilder::from_bytes(&secret_key);
20→/// let (token, cid) = builder.build(decision).await?;
21→/// ```
22→pub struct GurkhaPermitBuilder {
23→    signing_key_bytes: [u8; 32],
24→}
25→
26→impl GurkhaPermitBuilder {
27→    /// Create a new builder from signing key bytes
28→    pub fn from_bytes(signing_key_bytes: &[u8; 32]) -> Self {
29→        Self {
30→            signing_key_bytes: *signing_key_bytes,
31→        }
32→    }
33→
34→    /// Build a permit token from a decision
35→    ///
36→    /// Takes a TokenDecision and constructs the actual token with:
37→    /// - Capabilities from the decision
38→    /// - Facts from the decision
39→    /// - Proof chain (prf field) from decision.proofs
40→    /// - Embedded proof tokens (prf_tokens fact) from decision.proof_tokens
41→    ///
42→    /// # Returns
43→    /// - `Ok((token_string, cid))` - The JWT token and its CID
44→    /// - `Err(GurkhaError)` - If token construction fails
45→    pub async fn build(&self, decision: TokenDecision) -> Result<(String, String), GurkhaError> {
46→        debug!("Building permit token from decision");
47→        debug!("  Audience: {}", decision.audience);
48→        debug!("  Capabilities: {:?}", decision.capabilities);
49→        debug!("  Proofs in chain: {}", decision.proofs.len());
50→        debug!("  Embedded proof tokens: {}", decision.proof_tokens.len());
51→
52→        let result = sign_permit(&self.signing_key_bytes, &decision).await?;
53→
54→        info!("Permit token built successfully");
55→        debug!("  CID: {}", result.1);
56→
57→        Ok(result)
58→    }
59→}
