  1→//! Layer Pattern Authorization
  2→//!
  3→//! Functions for checking if a permit authorizes access to a layer.
  4→//! Supports two-tier access: page permit (static layers) + layer permits (dynamic layers).
  5→
  6→/// Check if permit authorizes access to a layer
  7→///
  8→/// With fully-resolved permits, this is a simple map lookup.
  9→/// Layer keys in the permit are already expanded (e.g., "abc123/products").
 10→///
 11→/// # Arguments
 12→/// * `permit` - The viewer's permit
 13→/// * `layer_name` - Name of the layer to access (bare or full)
 14→/// * `operation` - Operation to check: "read", "write", "sync"
 15→///
 16→/// # Returns
 17→/// `true` if the permit authorizes this layer access
 18→pub fn can_access_layer(permit: &crate::parser::Permit, layer_name: &str, operation: &str) -> bool {
 19→    let page_id = permit.get_fact("page_id")
 20→        .and_then(|v| v.as_str())
 21→        .unwrap_or("");
 22→
 23→    // Try direct lookup first
 24→    if let Some(config) = permit.layers().get(layer_name) {
 25→        return check_operation(config, operation);
 26→    }
 27→
 28→    // Try with page_id prefix (for bare names like "products")
 29→    let full_name = format!("{}/{}", page_id, layer_name);
 30→    if let Some(config) = permit.layers().get(&full_name) {
 31→        return check_operation(config, operation);
 32→    }
 33→
 34→    // Try stripping page_id prefix (for full names when permit has bare)
 35→    let page_prefix = format!("{}/", page_id);
 36→    if let Some(bare) = layer_name.strip_prefix(&page_prefix) {
 37→        if let Some(config) = permit.layers().get(bare) {
 38→            return check_operation(config, operation);
 39→        }
 40→    }
 41→
 42→    tracing::debug!("[can_access_layer] No layer match for '{}'", layer_name);
 43→    false
 44→}
 45→
 46→/// Check access across a page permit + set of layer permits (two-tier model)
 47→///
 48→/// **Context**: Dynamic layers are authorized via separate layer permits.
 49→/// This function checks if any permit in the set grants access to the layer.
 50→///
 51→/// Access check = page permit layers ∪ all layer permit layers
 52→pub fn can_access_with_layer_permits(
 53→    page_permit: &crate::parser::Permit,
 54→    layer_permits: &[crate::parser::Permit],
 55→    layer_name: &str,
 56→    page_id: &str,
 57→    did: &str,
 58→    operation: &str,
 59→) -> bool {
 60→    // Check page permit first
 61→    if can_access_layer(page_permit, layer_name, operation) {
 62→        return true;
 63→    }
 64→
 65→    // Check each layer permit
 66→    for lp in layer_permits {
 67→        if can_access_layer(lp, layer_name, operation) {
 68→            return true;
 69→        }
 70→    }
 71→
 72→    // Schema fallback: creator can access dynamic layers matching their own DID in path
 73→    if matches_creator_schema(page_permit, layer_name, page_id, did, operation) {
 74→        return true;
 75→    }
 76→
 77→    false
 78→}
 79→
 80→/// Check if a layer matches a dynamic schema for a given role (node-side auth)
 81→///
 82→/// **Context**: Node needs to authorize writes from peers to dynamic layers.
 83→/// The peer's page permit doesn't cover the dynamic layer (it has another user's DID in the path).
 84→/// Instead, the node checks its own permit's `dynamic_layer_schemas` + the peer's role.
 85→///
 86→/// **Example**: Bob (collaborator) writes to `channels/did:key:alice/project-x/messages`.
 87→/// Node's permit has schema `channels/{id}/messages` with `role_permissions.collaborator.write = true`.
 88→/// The path structure matches the schema → write is allowed.
 89→pub fn matches_dynamic_schema_for_role(
 90→    permit: &crate::parser::Permit,
 91→    layer_name: &str,
 92→    page_id: &str,
 93→    role: &str,
 94→    operation: &str,
 95→) -> bool {
 96→    let schemas = permit.dynamic_layer_schemas();
 97→    if schemas.is_empty() {
 98→        return false;
 99→    }
100→
101→    // Strip page_id prefix to get bare layer path
102→    let page_prefix = format!("{}/", page_id);
103→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
104→
105→    for (schema_pattern, schema) in schemas {
106→        if matches_dynamic_path_any_did(bare_path, schema_pattern) {
107→            // Check role_permissions (for role-granted schemas)
108→            if let Some(perm) = schema.role_permissions.get(role) {
109→                if check_operation(perm, operation) {
110→                    return true;
111→                }
112→            }
113→            // Check general permissions (for explicit grant schemas)
114→            if let Some(ref config) = schema.permissions {
115→                if check_operation(config, operation) {
116→                    return true;
117→                }
118→            }
119→        }
120→    }
121→
122→    false
123→}
124→
125→/// Match a layer path against a dynamic schema pattern (any DID accepted)
126→///
127→/// **Context**: Unlike `matches_dynamic_path`, this doesn't require a specific DID.
128→/// Used for node-side authorization where the peer writing isn't the creator.
129→///
130→/// **Pattern**: `channels/{id}/messages`
131→/// **Path**:    `channels/did:key:alice/project-x/messages`
132→///
133→/// Accepts any value in the DID position (path_parts[1]).
134→fn matches_dynamic_path_any_did(bare_path: &str, schema_pattern: &str) -> bool {
135→    let path_parts: Vec<&str> = bare_path.split('/').collect();
136→    let pattern_parts: Vec<&str> = schema_pattern.split('/').collect();
137→
138→    // Dynamic path has one extra segment (the DID) compared to schema pattern
139→    if path_parts.len() != pattern_parts.len() + 1 {
140→        return false;
141→    }
142→
143→    // First segment must match literally
144→    if path_parts.is_empty() || pattern_parts.is_empty() || path_parts[0] != pattern_parts[0] {
145→        return false;
146→    }
147→
148→    // path_parts[1] is the DID segment — accept any value (no specific DID check)
149→
150→    // Remaining segments: match path[2..] against pattern[1..]
151→    for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
152→        if *pat_seg != "{id}" && path_seg != pat_seg {
153→            return false;
154→        }
155→    }
156→
157→    true
158→}
159→
160→/// Schema fallback for creator access to dynamic layers
161→///
162→/// **Context**: When a creator creates a dynamic layer, they can access it immediately
163→/// via schema matching (before the node issues a layer permit). The layer path must
164→/// contain the creator's DID to prove ownership.
165→///
166→/// **Example**: Creator with DID `did:key:alice` and schema `channels/{id}/messages`
167→/// can access `page1/channels/did:key:alice/general/messages` because:
168→/// 1. Schema `channels/{id}/messages` exists in their permit
169→/// 2. The path contains their DID after stripping page_id prefix
170→pub fn matches_creator_schema(
171→    permit: &crate::parser::Permit,
172→    layer_name: &str,
173→    page_id: &str,
174→    our_did: &str,
175→    operation: &str,
176→) -> bool {
177→    let schemas = permit.dynamic_layer_schemas();
178→    if schemas.is_empty() {
179→        return false;
180→    }
181→
182→    // Strip page_id prefix to get bare layer path
183→    let page_prefix = format!("{}/", page_id);
184→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
185→
186→    // For creator access, the path must contain the creator's DID
187→    // Path format: {schema_prefix}/{creator_did}/{id_segments}/{schema_suffix}
188→    if !bare_path.contains(our_did) {
189→        return false;
190→    }
191→
192→    // Try to match against each schema pattern
193→    // Schema pattern: "channels/{id}/messages"
194→    // Layer path:     "channels/did:key:alice/general/messages"
195→    // We need to check if the path matches the schema with DID inserted
196→    for (schema_pattern, schema) in schemas {
197→        if matches_dynamic_path(bare_path, schema_pattern, our_did) {
198→            let config = schema.permissions.as_ref().cloned().unwrap_or(
199→                crate::parser::LayerConfig { sync: true, write: true, layer_type: None }
200→            );
201→            if check_operation(&config, operation) {
202→                return true;
203→            }
204→        }
205→    }
206→
207→    false
208→}
209→
210→/// Check if a layer path matches a dynamic schema pattern with a DID inserted
211→///
212→/// Schema patterns use `{id}` as wildcard. For creator access, the DID is
213→/// inserted as an additional path segment after the first literal segment.
214→///
215→/// **Pattern**: `channels/{id}/messages`
216→/// **Path**:    `channels/did:key:alice/general/messages`
217→///
218→/// The DID segment (`did:key:alice`) is the creator's namespace.
219→/// The `{id}` matches the user-chosen ID (`general`).
220→fn matches_dynamic_path(bare_path: &str, schema_pattern: &str, creator_did: &str) -> bool {
221→    let path_parts: Vec<&str> = bare_path.split('/').collect();
222→    let pattern_parts: Vec<&str> = schema_pattern.split('/').collect();
223→
224→    // Dynamic path has one extra segment (the DID) compared to schema pattern
225→    if path_parts.len() != pattern_parts.len() + 1 {
226→        return false;
227→    }
228→
229→    // First segment must match literally
230→    if path_parts.is_empty() || pattern_parts.is_empty() || path_parts[0] != pattern_parts[0] {
231→        return false;
232→    }
233→
234→    // Second segment in path must be the creator's DID
235→    if path_parts.len() < 2 || path_parts[1] != creator_did {
236→        return false;
237→    }
238→
239→    // Remaining segments: match path[2..] against pattern[1..]
240→    for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
241→        if *pat_seg != "{id}" && path_seg != pat_seg {
242→            return false;
243→        }
244→    }
245→
246→    true
247→}
248→
249→/// Check if a layer config allows the given operation
250→fn check_operation(config: &crate::parser::LayerConfig, operation: &str) -> bool {
251→    match operation {
252→        "read" => config.sync,
253→        "write" => config.write,
254→        "sync" => config.sync,
255→        _ => false,
256→    }
257→}
