550→/// Issue a space sync consent permit
551→///
552→/// **Context**: Viewer issues this permit back to the node after receiving SpaceSync.
553→/// It expresses the viewer's consent to receive sync updates and new pages for this space.
554→///
555→/// **Issued by**: Viewer
556→/// **Audience**: Node (specific node pubkey/DID)
557→/// **Proof**: Node's original viewer permit (establishes delegation chain)
558→///
559→/// # Arguments
560→/// * `signing_key_bytes` - Viewer's 32-byte Ed25519 secret key
561→/// * `node_pubkey` - Node's public key (audience of the consent permit)
562→/// * `space_id` - Space identifier
563→/// * `node_viewer_permit` - Node's original permit issued to the viewer (used as proof)
564→/// * `template_json` - JSON template for the consent permit (SYNC_SPACE_CONSENT_TEMPLATE)
565→///
566→/// # Returns
567→/// * `Ok((token, cid))` - The consent permit token and its CID
568→#[instrument(skip(signing_key_bytes, node_viewer_permit, template_json), fields(space_id = %space_id, token_type = "sync_space_consent"))]
569→pub async fn issue_sync_space_consent(
570→    signing_key_bytes: &[u8; 32],
571→    node_pubkey: &str,
572→    space_id: &str,
573→    node_viewer_permit: &str,
574→    template_json: &str,
575→) -> ServiceResult<(String, String)> {
576→    trace!("Issuing space sync consent permit");
577→
578→    let signing_key = SigningKey::from_bytes(signing_key_bytes);
579→    let verifying_key = signing_key.verifying_key();
580→
581→    let token_decision = decision::decide_sync_space_consent(
582→        &verifying_key,
583→        node_pubkey,
584→        space_id,
585→        node_viewer_permit,
586→        template_json,
587→    )?;
588→
589→    let (token, cid) = crypto::sign_permit(signing_key_bytes, &token_decision).await?;
590→
591→    info!("Space sync consent permit issued: cid={}", cid);
592→    Ok((token, cid))
593→}
