 1→//! Page Bindings for Lua
 2→//!
 3→//! Provides `page:on_change()` API for registering layer event handlers.
 4→
 5→use mlua::{Error as LuaError, RegistryKey, UserData, UserDataMethods};
 6→use std::sync::Arc;
 7→
 8→/// Registered page event handler
 9→pub struct PageHandler {
10→    /// Pattern to match (e.g., "{page_id}/orders/*")
11→    pub pattern: String,
12→    /// Lua function reference (stored in registry)
13→    pub callback: RegistryKey,
14→}
15→
16→/// Page bindings providing `page:on_change()` and `page:open_app()` APIs
17→///
18→/// **Usage in Lua**:
19→/// ```lua
20→/// page:on_change("{page_id}/orders/*", function(event)
21→///     -- event.layer_name = "shop123/orders/did:key:customer"
22→///     -- event.event_type = "created" | "updated"
23→///     -- event.full_data = { ... }
24→///     local summary_layer = loro:get_layer("{page_id}/derived/orders_summary", "map")
25→///     summary_layer:set(event.full_data.id, transform(event.full_data))
26→/// end)
27→///
28→/// page:open_app("Protocol Docs")  -- navigate to sibling app in same page
29→/// ```
30→pub struct PageBindings {
31→    /// Registered handlers (pattern -> callback)
32→    pub handlers: Arc<std::sync::RwLock<Vec<PageHandler>>>,
33→    /// Page ID for pattern expansion
34→    pub page_id: String,
35→    /// Channel for in-page navigation (sends app name to tab switcher)
36→    pub navigate_tx: Option<std::sync::mpsc::Sender<String>>,
37→}
38→
39→impl UserData for PageBindings {
40→    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
41→        // page:on_change(pattern, callback)
42→        methods.add_method(
43→            "on_change",
44→            |lua, this, (pattern, callback): (String, mlua::Function)| {
45→                // Expand {page_id} in pattern, then strip page_id/ prefix
46→                // Scribe uses bare layer names (no page_id/ prefix)
47→                let expanded = pattern.replace("{page_id}", &this.page_id);
48→                let prefix = format!("{}/", this.page_id);
49→                let expanded_pattern = expanded.strip_prefix(&prefix)
50→                    .unwrap_or(&expanded)
51→                    .to_string();
52→
53→                // Store callback in Lua registry (keeps it alive)
54→                let registry_key = lua.create_registry_value(callback).map_err(|e| {
55→                    LuaError::RuntimeError(format!("Failed to store callback: {}", e))
56→                })?;
57→
58→                // Add handler
59→                let handler = PageHandler {
60→                    pattern: expanded_pattern.clone(),
61→                    callback: registry_key,
62→                };
63→
64→                if let Ok(mut handlers) = this.handlers.write() {
65→                    handlers.push(handler);
66→                    tracing::info!(
67→                        pattern = %expanded_pattern,
68→                        handler_count = handlers.len(),
69→                        "Registered page:on_change handler"
70→                    );
71→                }
72→
73→                Ok(())
74→            },
75→        );
76→
77→        // page:open_app(app_name) — navigate to a sibling app in the same page
78→        methods.add_method("open_app", |_lua, this, app_name: String| {
79→            if let Some(ref tx) = this.navigate_tx {
80→                tx.send(app_name.clone()).map_err(|e| {
81→                    LuaError::RuntimeError(format!("Failed to navigate to app '{}': {}", app_name, e))
82→                })?;
83→            }
84→            Ok(())
85→        });
86→    }
87→}
