  1→//! Test fixtures for creating signed permits
  2→//!
  3→//! Loads permit templates from test_permits/ directory and creates
  4→//! valid signed permits for integration testing.
  5→
  6→use crate::crypto::generate_permit_with_cid;
  7→use crate::parser::Permit;
  8→use serde_json::{json, Value};
  9→use std::collections::HashMap;
 10→use std::path::Path;
 11→
 12→/// Deterministic test signing key (32 bytes)
 13→const TEST_KEY: [u8; 32] = [1u8; 32];
 14→
 15→/// Load a permit template file from test_permits/
 16→pub fn load_template(filename: &str) -> Value {
 17→    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
 18→        .join("test_permits")
 19→        .join(filename);
 20→    let content = std::fs::read_to_string(&path)
 21→        .unwrap_or_else(|e| panic!("Failed to read {}: {}", path.display(), e));
 22→    serde_json::from_str(&content)
 23→        .unwrap_or_else(|e| panic!("Failed to parse {}: {}", path.display(), e))
 24→}
 25→
 26→/// Create a permit from a role in a template file
 27→///
 28→/// # Arguments
 29→/// * `filename` - Template file (e.g., "shop.json")
 30→/// * `role` - Role key in the template (e.g., "owner", "customer")
 31→/// * `page_id` - Page ID to inject into facts
 32→/// * `audience` - DID of the permit holder
 33→pub fn create_permit(filename: &str, role: &str, page_id: &str, audience: &str) -> Permit {
 34→    let template = load_template(filename);
 35→    let role_template = template[role].as_object()
 36→        .unwrap_or_else(|| panic!("Missing role '{}' in {}", role, filename));
 37→
 38→    // Build facts from template
 39→    let mut facts = serde_json::Map::new();
 40→
 41→    // Copy all fields from role template
 42→    for (key, value) in role_template {
 43→        facts.insert(key.clone(), value.clone());
 44→    }
 45→
 46→    // Inject page_id
 47→    facts.insert("page_id".to_string(), json!(page_id));
 48→
 49→    // Resolve {page_id} in layer keys and nested issue_on templates
 50→    crate::parser::resolve_page_id_in_facts(&mut facts, page_id);
 51→
 52→    // Resolve {aud} in layer keys (test-time resolution for explicit permits)
 53→    resolve_aud_in_layers(&mut facts, audience);
 54→
 55→    let (token, _cid) = pollster::block_on(generate_permit_with_cid(
 56→        &TEST_KEY,
 57→        audience,
 58→        vec![],              // No capabilities (facts-only architecture)
 59→        Some(facts),
 60→        None,                // No expiry
 61→        vec![],              // No proofs
 62→        HashMap::new(),      // No proof tokens
 63→    ))
 64→    .expect("Failed to create test permit");
 65→
 66→    Permit::from_token(&token).expect("Failed to parse test permit")
 67→}
 68→
 69→/// Create a permit token string from a role in a template file
 70→///
 71→/// Same as `create_permit` but returns the raw token string instead of parsed Permit.
 72→/// Useful for tests that need to pass the token to Subscribe messages.
 73→pub fn create_permit_token(filename: &str, role: &str, page_id: &str, audience: &str) -> String {
 74→    let template = load_template(filename);
 75→    let role_template = template[role].as_object()
 76→        .unwrap_or_else(|| panic!("Missing role '{}' in {}", role, filename));
 77→
 78→    // Build facts from template
 79→    let mut facts = serde_json::Map::new();
 80→
 81→    // Copy all fields from role template
 82→    for (key, value) in role_template {
 83→        facts.insert(key.clone(), value.clone());
 84→    }
 85→
 86→    // Inject page_id
 87→    facts.insert("page_id".to_string(), json!(page_id));
 88→
 89→    // Resolve {page_id} in layer keys and nested issue_on templates
 90→    crate::parser::resolve_page_id_in_facts(&mut facts, page_id);
 91→
 92→    // Resolve {aud} in layer keys (test-time resolution for explicit permits)
 93→    resolve_aud_in_layers(&mut facts, audience);
 94→
 95→    let (token, _cid) = pollster::block_on(generate_permit_with_cid(
 96→        &TEST_KEY,
 97→        audience,
 98→        vec![],              // No capabilities (facts-only architecture)
 99→        Some(facts),
100→        None,                // No expiry
101→        vec![],              // No proofs
102→        HashMap::new(),      // No proof tokens
103→    ))
104→    .expect("Failed to create test permit");
105→
106→    token
107→}
