223→/// Resolve {aud} placeholder in layer keys (test-time only)
224→///
225→/// In production, dynamic layers are added via permit re-issuance.
226→/// For test fixtures, we resolve {aud} at create time to simulate
227→/// explicit layer grants.
228→fn resolve_aud_in_layers(facts: &mut serde_json::Map<String, Value>, aud: &str) {
229→    if let Some(layers) = facts.remove("layers") {
230→        if let Some(layers_obj) = layers.as_object() {
231→            let mut resolved = serde_json::Map::new();
232→            for (key, val) in layers_obj {
233→                let resolved_key = key.replace("{aud}", aud);
234→                resolved.insert(resolved_key, val.clone());
235→            }
236→            facts.insert("layers".to_string(), Value::Object(resolved));
237→        }
238→    }
239→}
