13→/// Represents a decision about what should go in a token (before signing)
14→///
15→/// This is what decision functions return - pure data describing the token content.
16→/// The crypto layer then takes this and signs it.
17→#[derive(Debug, Clone)]
18→pub struct TokenDecision {
19→    pub audience: String,
20→    pub capabilities: Vec<(String, String)>,
21→    pub facts: Map<String, Value>,
22→    pub expiry: Option<u64>,
23→    /// Proof chain: Array of CIDs for the `prf` field (UCAN standard)
24→    pub proofs: Vec<String>,
25→    /// Embedded proof tokens: CID -> full JWT token mapping for `fct.prf_tokens` (extension)
26→    /// Enables stateless proof chain validation without database lookups
27→    pub proof_tokens: HashMap<String, String>,
28→}
29→
30→impl TokenDecision {
31→    pub fn new(audience: &str) -> Self {
32→        Self {
33→            audience: audience.to_string(),
34→            capabilities: Vec::new(),
35→            facts: Map::new(),
36→            expiry: None,
37→            proofs: Vec::new(),
38→            proof_tokens: HashMap::new(),
39→        }
40→    }
41→
42→    pub fn add_capability(&mut self, resource: String, ability: String) {
43→        self.capabilities.push((resource, ability));
44→    }
45→
46→    pub fn add_fact(&mut self, key: String, value: Value) {
47→        self.facts.insert(key, value);
48→    }
49→
50→    pub fn set_expiry(&mut self, seconds: u64) {
51→        self.expiry = Some(seconds);
52→    }
53→
54→    /// Set presence configuration (visibility, display name)
55→    ///
56→    /// **Context**: Controls whether this peer appears in /users layer and presence events
57→    pub fn with_presence(mut self, visible: bool, name: Option<String>) -> Self {
58→        let mut presence_obj = serde_json::Map::new();
59→        presence_obj.insert("visible".to_string(), Value::Bool(visible));
60→        if let Some(n) = name {
61→            presence_obj.insert("name".to_string(), Value::String(n));
62→        }
63→        self.facts.insert("presence".to_string(), Value::Object(presence_obj));
64→        self
65→    }
66→
67→    /// Set allowed ephemeral function names
68→    ///
69→    /// **Context**: Controls which ephemeral functions this peer can send
70→    /// **Empty list** = all functions allowed
71→    pub fn with_ephemeral_funcs(mut self, funcs: Vec<String>) -> Self {
72→        if !funcs.is_empty() {
73→            let funcs_arr: Vec<Value> = funcs.into_iter().map(Value::String).collect();
74→            self.facts.insert("ephemeral_funcs".to_string(), Value::Array(funcs_arr));
75→        }
76→        self
77→    }
78→}
