  2→//!
  3→//! This module provides minimal Ed25519 signing and verification for Permit tokens.
  4→//! No PGP operations - those belong in the service layer.
  5→
  6→use crate::errors::GurkhaError;
  7→use anyhow::{anyhow, Result as AnyResult};
  8→use async_trait::async_trait;
  9→use ed25519_dalek::{Signature, SigningKey, VerifyingKey};
 10→use serde_json::json;
 11→use ucan::{
 12→    builder::UcanBuilder,
 13→    capability::Capability,
 14→    crypto::{
 15→        did::{ED25519_MAGIC_BYTES},
 16→        JwtSignatureAlgorithm, KeyMaterial,
 17→    },
 18→};
 19→
 20→/// Ed25519 key material for Permit signing
 21→#[derive(Clone)]
 22→pub struct Ed25519KeyMaterial(pub VerifyingKey, pub Option<SigningKey>);
 23→
 24→impl Ed25519KeyMaterial {
 25→    pub fn new(signing_key: SigningKey, verifying_key: VerifyingKey) -> Self {
 26→        Self(verifying_key, Some(signing_key))
 27→    }
 28→}
 29→
 30→#[cfg_attr(target_arch = "wasm32", async_trait(?Send))]
 31→#[cfg_attr(not(target_arch = "wasm32"), async_trait)]
 32→impl KeyMaterial for Ed25519KeyMaterial {
 33→    fn get_jwt_algorithm_name(&self) -> String {
 34→        JwtSignatureAlgorithm::EdDSA.to_string()
 35→    }
 36→
 37→    async fn get_did(&self) -> AnyResult<String> {
 38→        let bytes = [ED25519_MAGIC_BYTES, self.0.as_bytes()].concat();
 39→        Ok(format!("did:key:z{}", bs58::encode(bytes).into_string()))
 40→    }
 41→
 42→    async fn sign(&self, payload: &[u8]) -> AnyResult<Vec<u8>> {
 43→        match &self.1 {
 44→            Some(private_key) => {
 45→                use ed25519_dalek::Signer;
 46→                let signature = private_key.sign(payload);
 47→                Ok(signature.to_bytes().to_vec())
 48→            }
 49→            None => Err(anyhow!("No private key; cannot sign data")),
 50→        }
 51→    }
 52→
 53→    async fn verify(&self, payload: &[u8], signature: &[u8]) -> AnyResult<()> {
 54→        let sig_array: [u8; 64] = signature
 55→            .try_into()
 56→            .map_err(|_| anyhow!("Invalid signature length"))?;
 57→        let signature = Signature::from_bytes(&sig_array);
 58→
 59→        use ed25519_dalek::Verifier;
 60→        self.0
 61→            .verify(payload, &signature)
 62→            .map_err(|e| anyhow!("Could not verify signature: {:?}", e))?;
 63→
 64→        Ok(())
 65→    }
 66→}
 67→
 68→/// Sign a permit token based on a decision structure
 69→///
 70→/// # Arguments
 71→/// * `signing_key_bytes` - 32-byte Ed25519 secret key
 72→/// * `decision` - Token decision containing audience, facts, etc.
 73→pub async fn sign_permit(
 74→    signing_key_bytes: &[u8; 32],
 75→    decision: &crate::decision::TokenDecision,
 76→) -> Result<(String, String), GurkhaError> {
 77→    // Enforce facts-only architecture - capabilities should always be empty
 78→    debug_assert!(
 79→        decision.capabilities.is_empty(),
 80→        "Permit v3 uses facts-only architecture. Capabilities vec should be empty. All authorization must be in facts."
 81→    );
 82→
 83→    generate_permit_with_cid(
 84→        signing_key_bytes,
 85→        &decision.audience,
 86→        decision.capabilities.clone(),
 87→        Some(decision.facts.clone()),
 88→        decision.expiry,
 89→        decision.proofs.clone(),
 90→        decision.proof_tokens.clone(),
 91→    )
 92→    .await
 93→}
 94→
 95→/// Generate a permit token with its CID hash
 96→///
 97→/// # Arguments
 98→/// * `signing_key_bytes` - 32-byte Ed25519 secret key
 99→/// * `capabilities` - UCAN capabilities (typically empty - auth is in facts)
100→/// * `facts` - Contains all authorization: operations, auth_capabilities, presence, etc.
101→pub async fn generate_permit_with_cid(
102→    signing_key_bytes: &[u8; 32],
103→    audience: &str,
104→    capabilities: Vec<(String, String)>,
105→    facts: Option<serde_json::Map<String, serde_json::Value>>,
106→    expiry_seconds: Option<u64>,
107→    proofs: Vec<String>,
108→    proof_tokens: std::collections::HashMap<String, String>,
109→) -> Result<(String, String), GurkhaError> {
110→    // 1. Reconstruct typed keys from bytes and create KeyMaterial
111→    let signing_key = SigningKey::from_bytes(signing_key_bytes);
112→    let verifying_key = signing_key.verifying_key();
113→    let key_material = Ed25519KeyMaterial::new(signing_key, verifying_key);
114→
115→    // 2. Set lifetime (default to 30 years if None)
116→    let lifetime = expiry_seconds.unwrap_or(30 * 365 * 24 * 60 * 60);
117→
118→    // 3. Build permit base (using UCAN library internally)
119→    let mut builder = UcanBuilder::default()
120→        .issued_by(&key_material)
121→        .for_audience(audience)
122→        .with_lifetime(lifetime);
123→
124→    // 4. Add capabilities (should be empty in v3 - all auth in facts)
125→    for (resource, ability) in capabilities {
126→        let cap = Capability::from((resource.as_str(), ability.as_str(), &json!({})));
127→        builder = builder.claiming_capability(cap);
128→    }
129→
130→    // 5. Add facts (v3: contains all authorization)
131→    // Facts structure: operations, relationship, auth_capabilities, peer_capabilities, presence, etc.
132→    let mut facts_map = facts.unwrap_or_default();
133→
134→    // Add prf_tokens if not empty (extension for self-contained validation)
135→    if !proof_tokens.is_empty() {
136→        facts_map.insert("prf_tokens".to_string(), json!(proof_tokens));
137→    }
138→
139→    for (key, value) in facts_map {
140→        builder = builder.with_fact(&key, value);
141→    }
142→
143→    // 6. Build signable with proofs
144→    let mut signable = builder
145→        .build()
146→        .map_err(|e| GurkhaError::CreationError(e.to_string()))?;
147→
148→    // Add proofs to the signable (will go into prf field)
149→    signable.proofs = proofs;
150→

