 61→/// Load page templates from permit_template.json
 62→///
 63→/// # Arguments
 64→/// * `page_dir` - Directory containing permit_template.json
 65→///
 66→/// # Returns
 67→/// * `Ok(PageTemplateResult)` - Permit template and layer names from JSON file
 68→/// * `Err(ButlerError)` - If permit_template.json is missing or invalid
 69→#[instrument(skip_all)]
 70→fn load_page_templates(page_dir: &Path) -> Result<PageTemplateResult> {
 71→    let permit_template_path = page_dir.join("permit_template.json");
 72→
 73→    if !permit_template_path.exists() {
 74→        return Err(ButlerError::Database(
 75→            format!("Page directory must contain permit_template.json: {}", page_dir.display())
 76→        ));
 77→    }
 78→
 79→    // Load permit template from JSON file
 80→    let permit_json = std::fs::read_to_string(&permit_template_path)
 81→        .map_err(|e| ButlerError::Database(
 82→            format!("Failed to read permit_template.json: {}", e)
 83→        ))?;
 84→
 85→    // Extract layer names from the permit template
 86→    let layer_names = extract_layer_names_from_permit(&permit_json)?;
 87→
 88→    tracing::info!(
 89→        layer_count = layer_names.len(),
 90→        "Loaded permit_template.json"
 91→    );
 92→
 93→    Ok(PageTemplateResult {
 94→        page_name: None, // Page name comes from directory or manifest
 95→        permit_template: permit_json,
 96→        layer_names,
