100→/// Extract layer names from permit template JSON
101→#[instrument(skip_all)]
102→fn extract_layer_names_from_permit(permit_json: &str) -> Result<Vec<String>> {
103→    let permit: serde_json::Value = serde_json::from_str(permit_json)
104→        .map_err(|e| ButlerError::Serialization(
105→            format!("Failed to parse permit template: {}", e)
106→        ))?;
107→
108→    let layers = permit.get("owner_template")
109→        .and_then(|t| t.get("layers"))
110→        .and_then(|l| l.as_object())
111→        .ok_or_else(|| ButlerError::permit_error(
112→            "Permit template missing owner_template.layers"
113→        ))?;
114→
115→    Ok(layers.keys().map(|k| k.to_string()).collect())
116→}
