118→/// Collect app files from a directory
119→///
120→/// Returns a HashMap of relative_path -> content for text files.
121→#[instrument(skip_all)]
122→fn collect_app_files(app_dir: &Path) -> Result<HashMap<String, String>> {
123→    let mut files = HashMap::new();
124→
125→    for entry in WalkDir::new(app_dir).into_iter().filter_map(|e| e.ok()) {
126→        let path = entry.path();
127→        if !path.is_file() {
128→            continue;
129→        }
130→
131→        let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
132→        if !["slint", "lua", "json"].contains(&ext) {
133→            continue;
134→        }
135→
136→        if let Ok(relative_path) = path.strip_prefix(app_dir) {
137→            let relative_str = relative_path.to_string_lossy().to_string();
138→            if let Ok(content) = std::fs::read_to_string(path) {
139→                files.insert(relative_str, content);
140→            }
141→        }
142→    }
143→
144→    Ok(files)
145→}
