147→/// Import an app from a directory into Butler storage
148→#[instrument(skip(butler, app_dir), fields(space_id = %space_id))]
149→pub async fn import_app_from_directory(
150→    butler: &Butler,
151→    space_id: &str,
152→    app_dir: &Path,
153→) -> Result<Page> {
154→    // 1. Read and parse manifest
155→    let manifest_path = app_dir.join("manifest.json");
156→    let manifest_content = std::fs::read_to_string(&manifest_path)
157→        .map_err(|e| ButlerError::Database(
158→            format!("Failed to read manifest.json: {}", e)
159→        ))?;
160→
161→    let manifest: serde_json::Value = serde_json::from_str(&manifest_content)
162→        .map_err(|e| ButlerError::Serialization(
163→            format!("Invalid manifest.json: {}", e)
164→        ))?;
165→
166→    let app_name = manifest.get("name")
167→        .and_then(|n| n.as_str())
168→        .ok_or_else(|| ButlerError::Database(
169→            "manifest.json missing 'name' field".to_string()
170→        ))?;
171→
172→    // 2. Read permit template
173→    let template_filename = manifest.get("permit_template")
174→        .and_then(|p| p.as_str())
175→        .unwrap_or("permit_template.json");
176→
177→    let template_path = app_dir.join(template_filename);
178→    let permit_template = std::fs::read_to_string(&template_path)
179→        .map_err(|e| ButlerError::Database(
180→            format!("Failed to read {}: {}", template_filename, e)
181→        ))?;
182→
183→    // 3. Collect all app files
184→    let files = collect_app_files(app_dir)?;
185→
186→    tracing::info!(
187→        app_name = %app_name,
188→        file_count = files.len(),
189→        space_id = %space_id,
190→        "Importing app to Butler storage"
191→    );
192→
193→    // 4. Extract data layer names from permit template
194→    let mut layer_names = extract_layer_names_from_permit(&permit_template)?;
195→
196→    // 5. Add app layer to the list
197→    let app_layer_name = app_layer_name(app_name);
198→    layer_names.push(app_layer_name.clone());
199→
200→    tracing::debug!(
201→        data_layer_count = layer_names.len() - 1,
202→        app_layer = %app_layer_name,
203→        "Creating page with layers"
204→    );
205→
206→    // 6. Create page with all layers (data + app)
207→    let page = butler.pages().create(
208→        space_id,
209→        app_name,
210→        layer_names,
211→        &permit_template,
212→    ).await?;
213→
214→    tracing::info!(page_id = %page.id, page_name = %page.name, "Created page for app");
215→
216→    // 7. Populate app layer with files
217→    // Get AES key by decrypting page
218→    let (_decrypted, aes_key) = butler.pages().get_decrypted(&page.id).await?;
219→
220→    // Create app layer with files
221→    let app_layer = Layer::new();
222→    app_layer.set_all_files(&files)?;
223→
224→    // Export, encrypt, and store
225→    let snapshot = app_layer.export_snapshot();
226→    let encrypted = herald::encrypt_symmetric(&aes_key, &snapshot)
227→        .map_err(|e| ButlerError::Encryption(e.to_string()))?;
228→
229→    butler.store().put_layer(&page.id, &app_layer_name, &encrypted)?;
230→
231→    tracing::info!(
232→        page_id = %page.id,
233→        app_name = %app_name,
234→        file_count = files.len(),
235→        "Successfully imported app with files in CRDT layer"
236→    );
237→
238→    Ok(page)
239→}
