241→/// Refresh an app from directory (re-read files and update layer)
242→///
243→/// Returns list of changed file paths.
244→#[instrument(skip(butler, app_dir), fields(page_id = %page_id, app_name = %app_name))]
245→pub async fn refresh_app_from_directory(
246→    butler: &Butler,
247→    page_id: &str,
248→    app_name: &str,
249→    app_dir: &Path,
250→) -> Result<Vec<String>> {
251→    // Verify page exists
252→    butler.pages().get(page_id)?
253→        .ok_or_else(|| ButlerError::NotFound(
254→            format!("Page {} not found", page_id)
255→        ))?;
256→
257→    // Collect new files from disk
258→    let new_files = collect_app_files(app_dir)?;
259→
260→    // Get AES key and current layer
261→    let (decrypted, aes_key) = butler.pages().get_decrypted(page_id).await?;
262→
263→    let app_layer_name = app_layer_name(app_name);
264→
265→    // Load existing app layer or create new
266→    let app_layer = if let Some(layer_bytes) = decrypted.docs.get(&app_layer_name) {
267→        if layer_bytes.is_empty() {
268→            Layer::new()
269→        } else {
270→            Layer::from_snapshot(layer_bytes)
271→                .unwrap_or_else(|_| Layer::new())
272→        }
273→    } else {
274→        Layer::new()
275→    };
276→
277→    // Get current files to compare
278→    let old_files = app_layer.get_all_files();
279→
280→    // Find changed files
281→    let mut changed_files = Vec::new();
282→    for (path, content) in &new_files {
283→        if old_files.get(path) != Some(content) {
284→            changed_files.push(path.clone());
285→        }
286→    }
287→    // Also track deleted files
288→    for path in old_files.keys() {
289→        if !new_files.contains_key(path) {
290→            changed_files.push(path.clone());
291→        }
292→    }
293→
294→    if changed_files.is_empty() {
295→        tracing::info!(page_id = %page_id, app_name = %app_name, "No changes detected");
296→        return Ok(changed_files);
297→    }
298→
299→    // Update layer with new files
300→    app_layer.set_all_files(&new_files)?;

