 77→fn issue_creator_layer_authority_permits(
 78→    state: &ScribeState,
 79→    full_layer_name: &str,
 80→    schema: &gurkha::DynamicLayerSchema,
 81→) {
 82→    let Some(ref issuer) = state.permit_issuer else { return; };
 83→
 84→    let mut targets: Vec<(String, Option<String>)> = Vec::new();
 85→    if let Ok(subs) = state.subscribers.read() {
 86→        for ((did, _device), info) in subs.iter() {
 87→            let role = info
 88→                .permit
 89→                .get_fact("role")
 90→                .and_then(|v| v.as_str())
 91→                .map(|r| r.to_string())
 92→                .or_else(|| {
 93→                    info.permit
 94→                        .get_fact("relationship")
 95→                        .and_then(|v| v.as_str())
 96→                        .map(|r| r.to_string())
 97→                });
 98→            targets.push((did.clone(), role));
 99→        }
100→    }
101→
102→    for (audience, role) in targets {
103→        let Some(config) = authority_config_from_template(schema, role.as_deref()) else {
104→            warn!(
105→                page_id = %state.page_id,
106→                layer = %full_layer_name,
107→                audience = %audience,
108→                role = role.as_deref().unwrap_or("unknown"),
109→                "Skipping layer authority issuance: no matching template config"
110→            );
111→            continue;
112→        };
113→
114→        match issuer.issue_layer_authority_permit(
115→            &audience,
116→            full_layer_name,
117→            config,
118→            None,
119→            1,
120→        ) {
121→            Ok((_token, _cid)) => {
122→                info!(
123→                    page_id = %state.page_id,
124→                    layer = %full_layer_name,
125→                    audience = %audience,
126→                    "Issued creator layer authority permit"
127→                );
128→            }
129→            Err(e) => {
130→                warn!(
131→                    page_id = %state.page_id,
132→                    layer = %full_layer_name,
133→                    audience = %audience,
134→                    error = %e,
135→                    "Failed to issue creator layer authority permit"
136→                );
137→            }
138→        }
139→    }
140→}
