142→fn authority_config_from_template(
143→    schema: &gurkha::DynamicLayerSchema,
144→    role: Option<&str>,
145→) -> Option<gurkha::LayerConfig> {
146→    let mut config = match schema.grant {
147→        gurkha::GrantType::Explicit => schema.permissions.clone(),
148→        gurkha::GrantType::Role => role.and_then(|r| schema.role_permissions.get(r).cloned()),
149→    }?;
150→
151→    if config.layer_type.is_none() && !schema.layer_type.is_empty() {
152→        config.layer_type = Some(schema.layer_type.clone());
153→    }
154→
155→    Some(config)
156→}
