158→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
159→///
160→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
161→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
162→///
163→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
164→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
165→    let parts: Vec<&str> = schema_key.split('/').collect();
166→    let mut result = Vec::new();
167→
168→    if parts.is_empty() {
169→        return format!("{}/{}", our_did, layer_id);
170→    }
171→
172→    // First segment: literal
173→    result.push(parts[0].to_string());
174→
175→    // Insert our DID as the second segment (namespace)
176→    result.push(our_did.to_string());
177→
178→    // Remaining segments: replace {id} with layer_id, keep literals
179→    for part in &parts[1..] {
180→        if *part == "{id}" {
181→            result.push(layer_id.to_string());
182→        } else {
183→            result.push(part.to_string());
184→        }
185→    }
186→
187→    result.join("/")
188→}
