190→/// Determine recipients and create layer permits for a new dynamic layer
191→///
192→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
193→/// **Returns**: Ready-to-send permits — courier just distributes them.
194→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
195→pub fn prepare_layer_permits(
196→    permit_issuer: &dyn PermitIssuer,
197→    page_id: &str,
198→    layer_name: &str,
199→    schema: &gurkha::DynamicLayerSchema,
200→    creator_did: &str,
201→    connected_peers: &[(String, String)],  // (did, role)
202→) -> Result<Vec<(String, String)>, String> {
203→    let mut permits = Vec::new();
204→
205→    match schema.grant {
206→        gurkha::GrantType::Role => {
207→            // Role-granted: all peers with matching roles get access
208→            for (did, role) in connected_peers {
209→                if let Some(perms) = schema.role_permissions.get(role) {
210→                    match permit_issuer.issue_layer_permit(did, layer_name, perms.clone(), None) {
211→                        Ok((token, _cid)) => {
212→                            info!(
213→                                page_id = %page_id,
214→                                layer = %layer_name,
215→                                recipient = %did,
216→                                role = %role,
217→                                "Issued role-based layer permit"
218→                            );
219→                            permits.push((did.clone(), token));
220→                        }
221→                        Err(e) => {
222→                            warn!(
223→                                page_id = %page_id,
224→                                layer = %layer_name,
225→                                recipient = %did,
226→                                error = %e,
227→                                "Failed to issue layer permit"
228→                            );
229→                        }
230→                    }
231→                }
232→            }
233→        }
234→        gurkha::GrantType::Explicit => {
235→            // Explicit-granted: authority-driven only (creator -> node permits).
236→            for (audience_did, _role) in connected_peers {
237→                let Some((config, intent_cid)) = authority_layer_config_and_intent(
238→                    permit_issuer,
239→                    audience_did,
240→                    layer_name,
241→                    page_id,
242→                ) else {
243→                    continue;
244→                };
245→
246→                match permit_issuer.issue_layer_permit(
247→                    audience_did,
248→                    layer_name,
249→                    config,
250→                    Some(&intent_cid),
251→                ) {
252→                    Ok((token, _cid)) => {
253→                        info!(
254→                            page_id = %page_id,
255→                            layer = %layer_name,
256→                            audience = %audience_did,
257→                            creator = %creator_did,
258→                            "Issued explicit layer permit from authority"
259→                        );
260→                        permits.push((audience_did.clone(), token));
261→                    }
262→                    Err(e) => {
263→                        warn!(
264→                            page_id = %page_id,
265→                            layer = %layer_name,
266→                            audience = %audience_did,
267→                            error = %e,
268→                            "Failed to issue explicit layer permit from authority"
269→                        );
270→                    }
271→                }
272→            }
273→        }
274→    }
275→
276→    Ok(permits)
277→}
