279→/// Find matching dynamic schema for a layer received from a peer
280→///
281→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
282→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
283→pub fn find_matching_dynamic_schema<'a>(
284→    permit: &'a gurkha::Permit,
285→    layer_name: &str,
286→    page_id: &str,
287→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
288→    let schemas = permit.dynamic_layer_schemas();
289→    if schemas.is_empty() {
290→        return None;
291→    }
292→
293→    // Strip page_id prefix to get bare layer path
294→    let page_prefix = format!("{}/", page_id);
295→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
296→
297→    let path_parts: Vec<&str> = bare_path.split('/').collect();
298→
299→    // Path must have at least 3 segments: prefix/did/id[/suffix]
300→    if path_parts.len() < 3 {
301→        return None;
302→    }
303→
304→    // Second segment should be a DID (the creator)
305→    let potential_creator = path_parts[1];
306→    if !potential_creator.starts_with("did:") {
307→        return None;
308→    }
309→
310→    // Try each schema pattern
311→    for (schema_key, schema) in schemas {
312→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
313→
314→        // Dynamic path has one extra segment (DID) compared to pattern
315→        if path_parts.len() != pattern_parts.len() + 1 {
316→            continue;
317→        }
318→
319→        // First segment must match literally
320→        if path_parts[0] != pattern_parts[0] {
321→            continue;
322→        }
323→
324→        // path[2..] must match pattern[1..] (with {id} as wildcard)
325→        let mut matched = true;
326→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
327→            if *pat_seg != "{id}" && path_seg != pat_seg {
328→                matched = false;
329→                break;
330→            }
331→        }
332→
333→        if matched {
334→            return Some((schema_key, schema, potential_creator.to_string()));
335→        }
336→    }
337→
338→    None
339→}
