341→/// Validate that a layer path created by a peer matches their DID (namespace security)
342→///
343→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
344→/// that the creator's DID is in the layer path (prevents namespace forgery).
345→///
346→/// **Returns**: true if the layer path contains the sender's DID
347→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
348→    let page_prefix = format!("{}/", page_id);
349→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
350→
351→    // The creator's DID must be the second segment in the path
352→    let parts: Vec<&str> = bare_path.split('/').collect();
353→    if parts.len() < 2 {
354→        return false;
355→    }
356→
357→    parts[1] == sender_did
358→}
