360→/// Handle AddLayerAccess message
361→///
362→/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
363→/// **We do**: Validate capability, require authority permit, issue permit if peer is subscribed
364→pub async fn handle_add_layer_access(
365→    state: &ScribeState,
366→    layer_name: &str,
367→    did: &str,
368→) -> Result<(), String> {
369→    // 1. Check our permit has manage_layer_access capability
370→    let permit = state.our_permit.as_ref().ok_or_else(|| {
371→        warn!(page_id = %state.page_id, layer = %layer_name, audience = %did, "AddLayerAccess rejected: missing our_permit");
372→        "No permit".to_string()
373→    })?;
374→    if !permit.can_manage_layer_access() {
375→        warn!(
376→            page_id = %state.page_id,
377→            layer = %layer_name,
378→            audience = %did,
379→            "AddLayerAccess rejected: missing manage_layer_access capability"
380→        );
381→        return Err("No manage_layer_access capability".into());
382→    }
383→
384→    // 2. Resolve schema/config and permit issuer
385→    let issuer = state.permit_issuer.as_ref().ok_or_else(|| {
386→        warn!(
387→            page_id = %state.page_id,
388→            layer = %layer_name,
389→            audience = %did,
390→            "AddLayerAccess rejected: no permit issuer (not node mode)"
391→        );
392→        "No permit issuer (not node mode)".to_string()
393→    })?;
394→    let (_schema_key, schema, _creator) = find_matching_dynamic_schema(permit, layer_name, &state.page_id)
395→        .ok_or_else(|| {
396→            warn!(
397→                page_id = %state.page_id,
398→                layer = %layer_name,
399→                audience = %did,
400→                "AddLayerAccess rejected: layer does not match dynamic schema"
401→            );
402→            "Layer does not match any dynamic schema".to_string()
403→        })?;
404→    if schema.grant != gurkha::GrantType::Explicit {
405→        warn!(
406→            page_id = %state.page_id,
407→            layer = %layer_name,
408→            audience = %did,
409→            "AddLayerAccess rejected: schema grant is not explicit"
410→        );
411→        return Err("AddLayerAccess only applies to explicit dynamic schemas".into());
412→    }
413→
414→    let (config, intent_cid, source) = if let Some((cfg, cid)) = authority_layer_config_and_intent(
415→        issuer.as_ref(),
416→        did,
417→        layer_name,
418→        &state.page_id,
419→    ) {
420→        (cfg, Some(cid), "authority")
421→    } else {
422→        let cfg = schema
423→            .permissions
424→            .clone()
425→            .ok_or_else(|| "Explicit schema missing permissions and no authority permit present".to_string())?;
426→        warn!(
427→            page_id = %state.page_id,
428→            layer = %layer_name,
429→            audience = %did,
430→            "No layer authority permit found; issuing access from explicit schema permissions"
431→        );
432→        (cfg, None, "schema_permissions")
433→    };
434→
435→    // 3. Issue permit (stored by coordinator even if peer is offline)
436→    let mut new_permits = Vec::new();
437→    match issuer.issue_layer_permit(did, layer_name, config, intent_cid.as_deref()) {
438→        Ok((token, _cid)) => {
439→            info!(
440→                page_id = %state.page_id,
441→                layer = %layer_name,
442→                audience = %did,
443→                source = %source,
444→                "Issued layer permit via AddLayerAccess"
445→            );
446→            new_permits.push((did.to_string(), token));
447→        }
448→        Err(e) => {
449→            warn!(error = %e, "Failed to issue layer permit for AddLayerAccess");
450→        }
451→    }
452→
453→    // 4. Add DID as subscriber on the LayerUnit (if permit was issued)
454→    if let Some((recipient_did, _token)) = new_permits.first() {
455→        let bare_name = crate::state::normalize_layer_name(layer_name, &state.page_id);
456→        let broadcast_tx = state.subscribers.read().ok().and_then(|subs| {
457→            subs.iter()
458→                .find(|((d, _), _)| d == recipient_did)
459→                .map(|(_, info)| info.broadcast_tx.clone())
460→        });
461→        if let (Some(unit), Some(tx)) = (state.units.get(&bare_name), broadcast_tx) {
462→            let caps = super::Capabilities { read: true, write: true, sync: true };
463→            unit.add_subscriber(recipient_did.clone(), caps, tx);
464→            state.emit_layer_auth_capture(&bare_name, recipient_did, "subscriber_added_add_access");
465→        }
466→    }
467→
468→    // 5. Emit LayerAccessChanged for Coordinator to store/distribute permit
469→    if !new_permits.is_empty() {
470→        if let Some(ref sync_event_tx) = state.sync_event_tx {
471→            let event = crate::SyncEvent::LayerAccessChanged {
472→                page_id: state.page_id.clone(),
473→                layer_name: layer_name.to_string(),
474→                permits: new_permits,
475→            };
476→            state.emit_sync_event_capture(&event);
477→            if let Err(e) = sync_event_tx.send(event).await {
478→                warn!(error = %e, "Failed to emit LayerAccessChanged");
479→            }
480→        }
481→    }
482→
483→    Ok(())
484→}
485→
486→/// Handle RemoveLayerAccess message
487→///
488→/// **Context**: Lua app calls scribe:remove_layer_access(layer_name, did)
489→/// **We do**: Validate capability, reject metadata-era revoke path
490→pub fn handle_remove_layer_access(
491→    state: &ScribeState,
492→    layer_name: &str,
493→    did: &str,
494→) -> Result<(), String> {
495→    let permit = state.our_permit.as_ref().ok_or("No permit")?;
496→    if !permit.can_manage_layer_access() {
497→        return Err("No manage_layer_access capability".into());
498→    }
499→
500→    let _ = layer_name;
501→    let _ = did;
502→    Err("RemoveLayerAccess is deprecated; rotate/revoke layer authority permits instead".to_string())
503→}
504→
505→fn authority_layer_config_and_intent(
506→    issuer: &dyn PermitIssuer,
507→    audience_did: &str,
508→    layer_name: &str,
509→    page_id: &str,
510→) -> Option<(gurkha::LayerConfig, String)> {
511→    let (_version, authority_token) = issuer
512→        .get_layer_authority_permit(audience_did, layer_name)
513→        .ok()
514→        .flatten()?;
515→
516→    let parsed = gurkha::Permit::from_token(&authority_token).ok()?;
517→    let config = if let Some(c) = parsed.layers().get(layer_name) {
518→        c.clone()
519→    } else {
520→        let bare = crate::state::normalize_layer_name(layer_name, page_id);
521→        parsed.layers().get(&bare)?.clone()
522→    };
523→
524→    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok()?;
525→    Some((config, intent_cid))
526→}
